FILES = {'apps/mobile/lib/core/weekly_officer_rules.dart': "class WeeklyOfficerRules {\n  const WeeklyOfficerRules._();\n\n  static String normalizeRole(String? value) {\n    return (value ?? '')\n        .trim()\n        .toLowerCase()\n        .replaceAll('á', 'a')\n        .replaceAll('ã', 'a')\n        .replaceAll('â', 'a')\n        .replaceAll('é', 'e')\n        .replaceAll('ê', 'e')\n        .replaceAll('í', 'i')\n        .replaceAll('ó', 'o')\n        .replaceAll('õ', 'o')\n        .replaceAll('ô', 'o')\n        .replaceAll('ú', 'u')\n        .replaceAll('-', '_')\n        .replaceAll(' ', '_');\n  }\n\n  static bool canManageRole(String? role, {bool superAdmin = false}) {\n    if (superAdmin) return true;\n    final normalized = normalizeRole(role);\n    return normalized == 'super_admin' ||\n        normalized == 'presidente' ||\n        normalized == 'president' ||\n        normalized == 'vice_presidente' ||\n        normalized == 'vice_president';\n  }\n\n  static bool countsAsOfficialDinner(Map<String, dynamic> row) {\n    final kind = row['dinner_kind']?.toString() ?? '';\n    final status = row['status']?.toString() ?? '';\n    return kind == 'regular' &&\n        (status == 'planned' || status == 'completed') &&\n        row['assigned_member_id'] != null;\n  }\n\n  static String displayMember(Map<String, dynamic>? member) {\n    if (member == null) return 'Sem responsável';\n    final nickname = member['nickname']?.toString().trim() ?? '';\n    if (nickname.isNotEmpty) return nickname;\n    final fullName = member['full_name']?.toString().trim() ?? '';\n    return fullName.isEmpty ? 'Membro' : fullName;\n  }\n\n  static String dinnerStatusLabel(String? status) => switch (status) {\n        'planned' => 'Planeado',\n        'closed' => 'Fechado',\n        'completed' => 'Concluído',\n        'cancelled' => 'Cancelado',\n        _ => status?.trim().isEmpty ?? true ? '—' : status!,\n      };\n\n  static String availabilityLabel(String? status) => switch (status) {\n        'active' => 'Ativo',\n        'absent' => 'Ausente',\n        'inactive' => 'Inativo',\n        _ => 'Ativo',\n      };\n\n  static String swapStatusLabel(String? status) => switch (status) {\n        'pending' => 'Pendente',\n        'accepted' => 'Aceite — aguarda Direção',\n        'rejected' => 'Recusada',\n        'applied' => 'Aplicada',\n        'cancelled' => 'Cancelada',\n        _ => status?.trim().isEmpty ?? true ? '—' : status!,\n      };\n}\n", 'apps/mobile/lib/repositories/weekly_officer_repository.dart': "import 'package:supabase_flutter/supabase_flutter.dart';\n\nimport '../core/app_config.dart';\nimport '../core/app_session.dart';\nimport '../core/weekly_officer_rules.dart';\n\nclass WeeklyOfficerRepository {\n  WeeklyOfficerRepository({SupabaseClient? client}) : _client = client;\n\n  final SupabaseClient? _client;\n\n  SupabaseClient get _supabase => _client ?? Supabase.instance.client;\n  String get _clubId => AppSession.instance.clubId;\n\n  bool get canManage => WeeklyOfficerRules.canManageRole(\n        AppSession.instance.role,\n        superAdmin: AppSession.instance.superAdmin,\n      );\n\n  Future<void> ensureYear(int year) async {\n    if (AppConfig.demoMode) return;\n    await _supabase.rpc(\n      'ensure_weekly_officer_schedule_v1',\n      params: {'target_club': _clubId, 'p_year': year},\n    );\n  }\n\n  Future<String?> currentMemberId() async {\n    if (AppConfig.demoMode) return null;\n    final response = await _supabase.rpc(\n      'current_weekly_officer_member_v1',\n      params: {'target_club': _clubId},\n    );\n    final value = response?.toString().trim() ?? '';\n    return value.isEmpty ? null : value;\n  }\n\n  Future<List<Map<String, dynamic>>> members() async {\n    if (AppConfig.demoMode) return const <Map<String, dynamic>>[];\n    final response = await _supabase\n        .from('members')\n        .select('id,member_number,full_name,nickname,status,primary_role,profile_id')\n        .eq('club_id', _clubId)\n        .limit(1000);\n    final rows = List<Map<String, dynamic>>.from(response);\n    rows.sort((a, b) {\n      final an = _int(a['member_number']) ?? 999999;\n      final bn = _int(b['member_number']) ?? 999999;\n      final byNumber = an.compareTo(bn);\n      if (byNumber != 0) return byNumber;\n      return (a['full_name']?.toString() ?? '')\n          .compareTo(b['full_name']?.toString() ?? '');\n    });\n    return rows;\n  }\n\n  Future<List<Map<String, dynamic>>> listRotation() async {\n    if (AppConfig.demoMode) return const <Map<String, dynamic>>[];\n    final response = await _supabase\n        .from('weekly_officer_rotation')\n        .select()\n        .eq('club_id', _clubId)\n        .order('rotation_order');\n    return List<Map<String, dynamic>>.from(response);\n  }\n\n  Future<List<Map<String, dynamic>>> listDinners(int year) async {\n    if (AppConfig.demoMode) return const <Map<String, dynamic>>[];\n    final start = '$year-01-01';\n    final end = '$year-12-31';\n    final response = await _supabase\n        .from('weekly_dinners')\n        .select()\n        .eq('club_id', _clubId)\n        .gte('dinner_date', start)\n        .lte('dinner_date', end)\n        .order('dinner_date');\n    return List<Map<String, dynamic>>.from(response);\n  }\n\n  Future<List<Map<String, dynamic>>> listAbsences(int year) async {\n    if (AppConfig.demoMode) return const <Map<String, dynamic>>[];\n    final start = '$year-01-01';\n    final end = '$year-12-31';\n    final response = await _supabase\n        .from('weekly_officer_absences')\n        .select()\n        .eq('club_id', _clubId)\n        .lte('starts_on', end)\n        .gte('ends_on', start)\n        .order('starts_on');\n    return List<Map<String, dynamic>>.from(response);\n  }\n\n  Future<List<Map<String, dynamic>>> listSwaps() async {\n    if (AppConfig.demoMode) return const <Map<String, dynamic>>[];\n    final response = await _supabase\n        .from('weekly_officer_swap_requests')\n        .select()\n        .eq('club_id', _clubId)\n        .order('created_at', ascending: false)\n        .limit(250);\n    return List<Map<String, dynamic>>.from(response);\n  }\n\n  Future<void> setMemberSettings({\n    required String memberId,\n    required bool enabled,\n    required String availabilityStatus,\n    required bool forceIncluded,\n    String? notes,\n  }) async {\n    await _supabase.rpc(\n      'set_weekly_officer_member_v1',\n      params: {\n        'target_club': _clubId,\n        'p_member': memberId,\n        'p_enabled': enabled,\n        'p_availability_status': availabilityStatus,\n        'p_force_included': forceIncluded,\n        'p_notes': _emptyToNull(notes),\n      },\n    );\n  }\n\n  Future<void> reorder(List<String> memberIds) async {\n    await _supabase.rpc(\n      'reorder_weekly_officer_v1',\n      params: {'target_club': _clubId, 'p_member_ids': memberIds},\n    );\n  }\n\n  Future<String> saveAbsence({\n    String? absenceId,\n    required String memberId,\n    required String kind,\n    required DateTime startsOn,\n    required DateTime endsOn,\n    String? notes,\n  }) async {\n    final response = await _supabase.rpc(\n      'save_weekly_officer_absence_v1',\n      params: {\n        'target_club': _clubId,\n        'p_absence': absenceId,\n        'p_member': memberId,\n        'p_absence_kind': kind,\n        'p_starts_on': _date(startsOn),\n        'p_ends_on': _date(endsOn),\n        'p_notes': _emptyToNull(notes),\n      },\n    );\n    return response.toString();\n  }\n\n  Future<void> deleteAbsence(String absenceId) async {\n    await _supabase.rpc(\n      'delete_weekly_officer_absence_v1',\n      params: {'target_club': _clubId, 'p_absence': absenceId},\n    );\n  }\n\n  Future<String> saveDinner({\n    String? dinnerId,\n    required DateTime date,\n    String? memberId,\n    String? externalName,\n    String? dish,\n    String? notes,\n    String status = 'planned',\n  }) async {\n    final response = await _supabase.rpc(\n      'save_weekly_dinner_v1',\n      params: {\n        'target_club': _clubId,\n        'p_dinner': dinnerId,\n        'p_date': _date(date),\n        'p_assigned_member': _emptyToNull(memberId),\n        'p_external_name': _emptyToNull(externalName),\n        'p_dish': _emptyToNull(dish),\n        'p_notes': _emptyToNull(notes),\n        'p_status': status,\n      },\n    );\n    return response.toString();\n  }\n\n  Future<void> setClosed({\n    required String dinnerId,\n    required bool closed,\n    String? notes,\n  }) async {\n    await _supabase.rpc(\n      'set_weekly_dinner_closed_v1',\n      params: {\n        'target_club': _clubId,\n        'p_dinner': dinnerId,\n        'p_closed': closed,\n        'p_notes': _emptyToNull(notes),\n      },\n    );\n  }\n\n  Future<String> requestSwap({\n    required String dinnerId,\n    required String requestedMemberId,\n    String? note,\n  }) async {\n    final response = await _supabase.rpc(\n      'request_weekly_officer_swap_v1',\n      params: {\n        'target_club': _clubId,\n        'p_dinner': dinnerId,\n        'p_requested_member': requestedMemberId,\n        'p_note': _emptyToNull(note),\n      },\n    );\n    return response.toString();\n  }\n\n  Future<void> respondSwap({\n    required String requestId,\n    required bool accept,\n    String? note,\n  }) async {\n    await _supabase.rpc(\n      'respond_weekly_officer_swap_v1',\n      params: {\n        'target_club': _clubId,\n        'p_request': requestId,\n        'p_accept': accept,\n        'p_note': _emptyToNull(note),\n      },\n    );\n  }\n\n  Future<void> markSwapApplied({\n    required String requestId,\n    String? note,\n  }) async {\n    await _supabase.rpc(\n      'mark_weekly_officer_swap_applied_v1',\n      params: {\n        'target_club': _clubId,\n        'p_request': requestId,\n        'p_note': _emptyToNull(note),\n      },\n    );\n  }\n\n  Future<void> cancelSwap(String requestId) async {\n    await _supabase.rpc(\n      'cancel_weekly_officer_swap_v1',\n      params: {'target_club': _clubId, 'p_request': requestId},\n    );\n  }\n\n  static int? _int(dynamic value) {\n    if (value is int) return value;\n    if (value is num) return value.toInt();\n    return int.tryParse(value?.toString() ?? '');\n  }\n\n  static String _date(DateTime value) =>\n      '${value.year.toString().padLeft(4, '0')}-'\n      '${value.month.toString().padLeft(2, '0')}-'\n      '${value.day.toString().padLeft(2, '0')}';\n\n  static String? _emptyToNull(String? value) {\n    final text = value?.trim() ?? '';\n    return text.isEmpty ? null : text;\n  }\n}\n", 'apps/mobile/lib/screens/weekly_officer_screen.dart': "import 'package:flutter/material.dart';\nimport 'package:intl/intl.dart';\nimport 'package:supabase_flutter/supabase_flutter.dart';\n\nimport '../core/weekly_officer_rules.dart';\nimport '../repositories/weekly_officer_repository.dart';\n\nclass WeeklyOfficerScreen extends StatefulWidget {\n  const WeeklyOfficerScreen({super.key});\n\n  @override\n  State<WeeklyOfficerScreen> createState() => _WeeklyOfficerScreenState();\n}\n\nclass _WeeklyOfficerScreenState extends State<WeeklyOfficerScreen> {\n  final WeeklyOfficerRepository _repository = WeeklyOfficerRepository();\n  late int _year;\n  late Future<_WeeklyOfficerData> _future;\n\n  bool get _canManage => _repository.canManage;\n\n  @override\n  void initState() {\n    super.initState();\n    _year = DateTime.now().year;\n    _reload();\n  }\n\n  void _reload() {\n    _future = _load();\n  }\n\n  Future<_WeeklyOfficerData> _load() async {\n    await _repository.ensureYear(_year);\n    final values = await Future.wait([\n      _repository.members(),\n      _repository.listRotation(),\n      _repository.listDinners(_year),\n      _repository.listAbsences(_year),\n      _repository.listSwaps(),\n      _repository.currentMemberId(),\n    ]);\n    return _WeeklyOfficerData(\n      members: List<Map<String, dynamic>>.from(values[0] as List),\n      rotation: List<Map<String, dynamic>>.from(values[1] as List),\n      dinners: List<Map<String, dynamic>>.from(values[2] as List),\n      absences: List<Map<String, dynamic>>.from(values[3] as List),\n      swaps: List<Map<String, dynamic>>.from(values[4] as List),\n      currentMemberId: values[5] as String?,\n    );\n  }\n\n  Future<void> _refresh() async {\n    setState(_reload);\n    await _future;\n  }\n\n  void _changeYear(int delta) {\n    setState(() {\n      _year += delta;\n      _reload();\n    });\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return FutureBuilder<_WeeklyOfficerData>(\n      future: _future,\n      builder: (context, snapshot) {\n        if (snapshot.connectionState == ConnectionState.waiting) {\n          return const Center(child: CircularProgressIndicator());\n        }\n        if (snapshot.hasError) {\n          return _ErrorState(\n            message: _errorText(snapshot.error),\n            onRetry: _refresh,\n          );\n        }\n        final data = snapshot.data ?? _WeeklyOfficerData.empty();\n        return DefaultTabController(\n          length: 4,\n          child: Column(\n            children: [\n              _yearHeader(data),\n              const TabBar(\n                isScrollable: true,\n                tabs: [\n                  Tab(icon: Icon(Icons.restaurant_outlined), text: 'Escala'),\n                  Tab(icon: Icon(Icons.sync_alt_outlined), text: 'Rotação'),\n                  Tab(icon: Icon(Icons.swap_horiz_outlined), text: 'Trocas'),\n                  Tab(icon: Icon(Icons.history_outlined), text: 'Histórico'),\n                ],\n              ),\n              Expanded(\n                child: TabBarView(\n                  children: [\n                    _scheduleTab(data),\n                    _rotationTab(data),\n                    _swapsTab(data),\n                    _historyTab(data),\n                  ],\n                ),\n              ),\n            ],\n          ),\n        );\n      },\n    );\n  }\n\n  Widget _yearHeader(_WeeklyOfficerData data) {\n    final next = data.nextRegularDinner;\n    final counts = data.officialCounts;\n    final activeIds = data.rotation\n        .where((row) => row['enabled'] != false)\n        .map((row) => row['member_id']?.toString())\n        .whereType<String>()\n        .toList();\n    final activeCounts = activeIds.map((id) => counts[id] ?? 0).toList();\n    final minCount = activeCounts.isEmpty\n        ? 0\n        : activeCounts.reduce((a, b) => a < b ? a : b);\n    final maxCount = activeCounts.isEmpty\n        ? 0\n        : activeCounts.reduce((a, b) => a > b ? a : b);\n\n    return Padding(\n      padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),\n      child: Column(\n        children: [\n          Row(\n            children: [\n              IconButton(\n                tooltip: 'Ano anterior',\n                onPressed: () => _changeYear(-1),\n                icon: const Icon(Icons.chevron_left),\n              ),\n              Expanded(\n                child: Text(\n                  'Escala $_year',\n                  textAlign: TextAlign.center,\n                  style: Theme.of(context).textTheme.titleLarge?.copyWith(\n                        fontWeight: FontWeight.w800,\n                      ),\n                ),\n              ),\n              IconButton(\n                tooltip: 'Ano seguinte',\n                onPressed: () => _changeYear(1),\n                icon: const Icon(Icons.chevron_right),\n              ),\n              IconButton(\n                tooltip: 'Atualizar',\n                onPressed: _refresh,\n                icon: const Icon(Icons.refresh),\n              ),\n            ],\n          ),\n          Card(\n            child: Padding(\n              padding: const EdgeInsets.all(14),\n              child: Row(\n                crossAxisAlignment: CrossAxisAlignment.start,\n                children: [\n                  const CircleAvatar(\n                    child: Icon(Icons.restaurant_menu_outlined),\n                  ),\n                  const SizedBox(width: 12),\n                  Expanded(\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        const Text(\n                          'Próximo Oficial da Semana',\n                          style: TextStyle(fontWeight: FontWeight.w800),\n                        ),\n                        const SizedBox(height: 4),\n                        Text(\n                          next == null\n                              ? 'Sem quinta-feira planeada.'\n                              : '${_datePt(next['dinner_date'])} · '\n                                  '${data.dinnerResponsible(next)}',\n                        ),\n                        const SizedBox(height: 4),\n                        Text(\n                          activeCounts.isEmpty\n                              ? 'Sem membros na rotação.'\n                              : 'Equidade anual: $minCount–$maxCount jantar(es) oficial(is) por membro.',\n                          style: Theme.of(context).textTheme.bodySmall,\n                        ),\n                      ],\n                    ),\n                  ),\n                  if (_canManage)\n                    FilledButton.icon(\n                      onPressed: () => _openDinnerDialog(data),\n                      icon: const Icon(Icons.add),\n                      label: const Text('Extra'),\n                    ),\n                ],\n              ),\n            ),\n          ),\n        ],\n      ),\n    );\n  }\n\n  Widget _scheduleTab(_WeeklyOfficerData data) {\n    if (data.dinners.isEmpty) {\n      return RefreshIndicator(\n        onRefresh: _refresh,\n        child: ListView(\n          physics: const AlwaysScrollableScrollPhysics(),\n          children: const [\n            SizedBox(height: 120),\n            Center(child: Text('Sem jantares neste ano.')),\n          ],\n        ),\n      );\n    }\n\n    return RefreshIndicator(\n      onRefresh: _refresh,\n      child: ListView.separated(\n        padding: const EdgeInsets.fromLTRB(16, 12, 16, 24),\n        itemCount: data.dinners.length,\n        separatorBuilder: (_, __) => const SizedBox(height: 8),\n        itemBuilder: (context, index) {\n          final row = data.dinners[index];\n          final regular = row['dinner_kind']?.toString() == 'regular';\n          final status = row['status']?.toString() ?? 'planned';\n          final assignedToCurrent = data.currentMemberId != null &&\n              row['assigned_member_id']?.toString() == data.currentMemberId &&\n              status == 'planned' &&\n              _dateFrom(row['dinner_date'])\n                  .isAfter(DateTime.now().subtract(const Duration(days: 1)));\n\n          return Card(\n            child: Padding(\n              padding: const EdgeInsets.fromLTRB(14, 12, 8, 12),\n              child: Row(\n                crossAxisAlignment: CrossAxisAlignment.start,\n                children: [\n                  SizedBox(\n                    width: 62,\n                    child: Column(\n                      children: [\n                        Text(\n                          DateFormat('dd', 'pt_PT')\n                              .format(_dateFrom(row['dinner_date'])),\n                          style: Theme.of(context).textTheme.headlineSmall?.copyWith(\n                                fontWeight: FontWeight.w900,\n                              ),\n                        ),\n                        Text(\n                          DateFormat('MMM', 'pt_PT')\n                              .format(_dateFrom(row['dinner_date']))\n                              .toUpperCase(),\n                          style: Theme.of(context).textTheme.labelSmall,\n                        ),\n                      ],\n                    ),\n                  ),\n                  const SizedBox(width: 10),\n                  Expanded(\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        Wrap(\n                          spacing: 6,\n                          runSpacing: 4,\n                          children: [\n                            Chip(\n                              visualDensity: VisualDensity.compact,\n                              label: Text(regular ? 'Quinta oficial' : 'Extraordinário'),\n                            ),\n                            Chip(\n                              visualDensity: VisualDensity.compact,\n                              label: Text(\n                                WeeklyOfficerRules.dinnerStatusLabel(status),\n                              ),\n                            ),\n                          ],\n                        ),\n                        const SizedBox(height: 4),\n                        Text(\n                          data.dinnerResponsible(row),\n                          style: const TextStyle(fontWeight: FontWeight.w800),\n                        ),\n                        if ((row['dish']?.toString().trim() ?? '').isNotEmpty)\n                          Text('Jantar: ${row['dish']}'),\n                        if ((row['notes']?.toString().trim() ?? '').isNotEmpty)\n                          Text(\n                            row['notes'].toString(),\n                            style: Theme.of(context).textTheme.bodySmall,\n                          ),\n                        if (assignedToCurrent && data.currentMemberId != null)\n                          Padding(\n                            padding: const EdgeInsets.only(top: 8),\n                            child: OutlinedButton.icon(\n                              onPressed: () => _requestSwap(data, row),\n                              icon: const Icon(Icons.swap_horiz),\n                              label: const Text('Pedir troca'),\n                            ),\n                          ),\n                      ],\n                    ),\n                  ),\n                  if (_canManage)\n                    PopupMenuButton<String>(\n                      onSelected: (action) async {\n                        if (action == 'edit') {\n                          await _openDinnerDialog(data, row);\n                        } else if (action == 'close') {\n                          await _setDinnerClosed(row, true);\n                        } else if (action == 'reopen') {\n                          await _setDinnerClosed(row, false);\n                        }\n                      },\n                      itemBuilder: (_) => [\n                        if (status != 'closed')\n                          const PopupMenuItem(\n                            value: 'edit',\n                            child: Text('Editar'),\n                          ),\n                        if (regular && status != 'closed')\n                          const PopupMenuItem(\n                            value: 'close',\n                            child: Text('Marcar quinta como fechada'),\n                          ),\n                        if (regular && status == 'closed')\n                          const PopupMenuItem(\n                            value: 'reopen',\n                            child: Text('Reabrir quinta-feira'),\n                          ),\n                      ],\n                    ),\n                ],\n              ),\n            ),\n          );\n        },\n      ),\n    );\n  }\n\n  Widget _rotationTab(_WeeklyOfficerData data) {\n    if (data.rotation.isEmpty) {\n      return const Center(child: Text('Sem membros na rotação.'));\n    }\n    final counts = data.officialCounts;\n    return RefreshIndicator(\n      onRefresh: _refresh,\n      child: ListView.builder(\n        padding: const EdgeInsets.fromLTRB(16, 12, 16, 24),\n        itemCount: data.rotation.length,\n        itemBuilder: (context, index) {\n          final row = data.rotation[index];\n          final memberId = row['member_id']?.toString() ?? '';\n          final member = data.memberById[memberId];\n          final absences = data.absences\n              .where((a) => a['member_id']?.toString() == memberId)\n              .toList();\n          final enabled = row['enabled'] != false;\n          final status = row['availability_status']?.toString() ?? 'active';\n          final force = row['force_included'] == true;\n\n          return Card(\n            margin: const EdgeInsets.only(bottom: 8),\n            child: Padding(\n              padding: const EdgeInsets.all(12),\n              child: Column(\n                children: [\n                  Row(\n                    children: [\n                      CircleAvatar(\n                        child: Text('${index + 1}'),\n                      ),\n                      const SizedBox(width: 12),\n                      Expanded(\n                        child: Column(\n                          crossAxisAlignment: CrossAxisAlignment.start,\n                          children: [\n                            Text(\n                              WeeklyOfficerRules.displayMember(member),\n                              style: const TextStyle(fontWeight: FontWeight.w800),\n                            ),\n                            Text(\n                              '${member?['primary_role'] ?? 'Membro'} · '\n                              '${counts[memberId] ?? 0} oficial(is)',\n                              style: Theme.of(context).textTheme.bodySmall,\n                            ),\n                          ],\n                        ),\n                      ),\n                      if (!enabled)\n                        const Chip(\n                          visualDensity: VisualDensity.compact,\n                          label: Text('Excluído'),\n                        )\n                      else if (force)\n                        const Chip(\n                          visualDensity: VisualDensity.compact,\n                          label: Text('Forçado'),\n                        )\n                      else if (status != 'active')\n                        Chip(\n                          visualDensity: VisualDensity.compact,\n                          label: Text(\n                            WeeklyOfficerRules.availabilityLabel(status),\n                          ),\n                        ),\n                      if (_canManage) ...[\n                        IconButton(\n                          tooltip: 'Subir',\n                          onPressed: index == 0\n                              ? null\n                              : () => _moveRotation(data, index, -1),\n                          icon: const Icon(Icons.arrow_upward),\n                        ),\n                        IconButton(\n                          tooltip: 'Descer',\n                          onPressed: index == data.rotation.length - 1\n                              ? null\n                              : () => _moveRotation(data, index, 1),\n                          icon: const Icon(Icons.arrow_downward),\n                        ),\n                        PopupMenuButton<String>(\n                          onSelected: (action) async {\n                            if (action == 'settings') {\n                              await _editRotationMember(data, row);\n                            } else if (action == 'absence') {\n                              await _addAbsence(data, memberId);\n                            }\n                          },\n                          itemBuilder: (_) => const [\n                            PopupMenuItem(\n                              value: 'settings',\n                              child: Text('Disponibilidade / inclusão'),\n                            ),\n                            PopupMenuItem(\n                              value: 'absence',\n                              child: Text('Adicionar férias / ausência'),\n                            ),\n                          ],\n                        ),\n                      ],\n                    ],\n                  ),\n                  if (absences.isNotEmpty) ...[\n                    const Divider(),\n                    ...absences.map(\n                      (absence) => Row(\n                        children: [\n                          Icon(\n                            absence['absence_kind'] == 'vacation'\n                                ? Icons.beach_access_outlined\n                                : Icons.event_busy_outlined,\n                            size: 18,\n                          ),\n                          const SizedBox(width: 8),\n                          Expanded(\n                            child: Text(\n                              '${absence['absence_kind'] == 'vacation' ? 'Férias' : 'Ausência'}: '\n                              '${_datePt(absence['starts_on'])}–${_datePt(absence['ends_on'])}',\n                              style: Theme.of(context).textTheme.bodySmall,\n                            ),\n                          ),\n                          if (_canManage)\n                            IconButton(\n                              tooltip: 'Remover período',\n                              visualDensity: VisualDensity.compact,\n                              onPressed: () => _deleteAbsence(absence),\n                              icon: const Icon(Icons.delete_outline, size: 18),\n                            ),\n                        ],\n                      ),\n                    ),\n                  ],\n                ],\n              ),\n            ),\n          );\n        },\n      ),\n    );\n  }\n\n  Widget _swapsTab(_WeeklyOfficerData data) {\n    if (data.swaps.isEmpty) {\n      return RefreshIndicator(\n        onRefresh: _refresh,\n        child: ListView(\n          physics: const AlwaysScrollableScrollPhysics(),\n          children: const [\n            SizedBox(height: 120),\n            Center(child: Text('Sem pedidos de troca.')),\n          ],\n        ),\n      );\n    }\n\n    return RefreshIndicator(\n      onRefresh: _refresh,\n      child: ListView.builder(\n        padding: const EdgeInsets.fromLTRB(16, 12, 16, 24),\n        itemCount: data.swaps.length,\n        itemBuilder: (context, index) {\n          final row = data.swaps[index];\n          final requesterId = row['requester_member_id']?.toString() ?? '';\n          final requestedId = row['requested_member_id']?.toString() ?? '';\n          final dinnerId = row['dinner_id']?.toString() ?? '';\n          final dinner = data.dinnerById[dinnerId];\n          final status = row['status']?.toString() ?? 'pending';\n          final isRecipient = data.currentMemberId == requestedId;\n          final isRequester = data.currentMemberId == requesterId;\n\n          return Card(\n            margin: const EdgeInsets.only(bottom: 8),\n            child: Padding(\n              padding: const EdgeInsets.all(14),\n              child: Column(\n                crossAxisAlignment: CrossAxisAlignment.start,\n                children: [\n                  Row(\n                    children: [\n                      Expanded(\n                        child: Text(\n                          '${WeeklyOfficerRules.displayMember(data.memberById[requesterId])} → '\n                          '${WeeklyOfficerRules.displayMember(data.memberById[requestedId])}',\n                          style: const TextStyle(fontWeight: FontWeight.w800),\n                        ),\n                      ),\n                      Chip(\n                        visualDensity: VisualDensity.compact,\n                        label: Text(WeeklyOfficerRules.swapStatusLabel(status)),\n                      ),\n                    ],\n                  ),\n                  Text(\n                    dinner == null\n                        ? 'Jantar não disponível'\n                        : 'Jantar de ${_datePt(dinner['dinner_date'])}',\n                  ),\n                  if ((row['requester_note']?.toString().trim() ?? '').isNotEmpty)\n                    Text('Nota: ${row['requester_note']}'),\n                  if ((row['response_note']?.toString().trim() ?? '').isNotEmpty)\n                    Text('Resposta: ${row['response_note']}'),\n                  if (status == 'accepted')\n                    Padding(\n                      padding: const EdgeInsets.only(top: 6),\n                      child: Text(\n                        'A aceitação não altera automaticamente a escala. '\n                        'Presidente/Vice-Presidente devem fazer a alteração efetiva.',\n                        style: Theme.of(context).textTheme.bodySmall,\n                      ),\n                    ),\n                  const SizedBox(height: 8),\n                  Wrap(\n                    spacing: 8,\n                    runSpacing: 8,\n                    children: [\n                      if (status == 'pending' && isRecipient)\n                        FilledButton.icon(\n                          onPressed: () => _respondSwap(row, true),\n                          icon: const Icon(Icons.check),\n                          label: const Text('Aceitar'),\n                        ),\n                      if (status == 'pending' && isRecipient)\n                        OutlinedButton.icon(\n                          onPressed: () => _respondSwap(row, false),\n                          icon: const Icon(Icons.close),\n                          label: const Text('Recusar'),\n                        ),\n                      if (status == 'pending' && (isRequester || _canManage))\n                        TextButton.icon(\n                          onPressed: () => _cancelSwap(row),\n                          icon: const Icon(Icons.cancel_outlined),\n                          label: const Text('Cancelar'),\n                        ),\n                      if (status == 'accepted' && _canManage)\n                        FilledButton.tonalIcon(\n                          onPressed: () => _markSwapApplied(row),\n                          icon: const Icon(Icons.done_all),\n                          label: const Text('Marcar como aplicada'),\n                        ),\n                    ],\n                  ),\n                ],\n              ),\n            ),\n          );\n        },\n      ),\n    );\n  }\n\n  Widget _historyTab(_WeeklyOfficerData data) {\n    final counts = data.officialCounts;\n    return RefreshIndicator(\n      onRefresh: _refresh,\n      child: ListView.builder(\n        padding: const EdgeInsets.fromLTRB(16, 12, 16, 24),\n        itemCount: data.rotation.length,\n        itemBuilder: (context, index) {\n          final rotation = data.rotation[index];\n          final memberId = rotation['member_id']?.toString() ?? '';\n          final member = data.memberById[memberId];\n          final official = data.dinners\n              .where(\n                (d) => WeeklyOfficerRules.countsAsOfficialDinner(d) &&\n                    d['assigned_member_id']?.toString() == memberId,\n              )\n              .toList()\n            ..sort(\n              (a, b) => _dateFrom(a['dinner_date'])\n                  .compareTo(_dateFrom(b['dinner_date'])),\n            );\n          final extras = data.dinners.where(\n            (d) => d['dinner_kind'] == 'extraordinary' &&\n                d['assigned_member_id']?.toString() == memberId &&\n                d['status'] != 'cancelled',\n          );\n          final completed = official\n              .where((d) => d['status'] == 'completed')\n              .toList();\n          final future = official.where(\n            (d) => !_dateFrom(d['dinner_date'])\n                .isBefore(DateTime(DateTime.now().year, DateTime.now().month, DateTime.now().day)),\n          );\n\n          return Card(\n            margin: const EdgeInsets.only(bottom: 8),\n            child: ListTile(\n              leading: CircleAvatar(child: Text('${counts[memberId] ?? 0}')),\n              title: Text(WeeklyOfficerRules.displayMember(member)),\n              subtitle: Text(\n                'Oficiais: ${counts[memberId] ?? 0} · Extras: ${extras.length}'\n                '${completed.isEmpty ? '' : ' · Último concluído: ${_datePt(completed.last['dinner_date'])}'}'\n                '${future.isEmpty ? '' : ' · Próximo: ${_datePt(future.first['dinner_date'])}'}',\n              ),\n            ),\n          );\n        },\n      ),\n    );\n  }\n\n  Future<void> _moveRotation(\n    _WeeklyOfficerData data,\n    int index,\n    int delta,\n  ) async {\n    final target = index + delta;\n    if (target < 0 || target >= data.rotation.length) return;\n    final ids = data.rotation\n        .map((row) => row['member_id']?.toString() ?? '')\n        .where((id) => id.isNotEmpty)\n        .toList();\n    final item = ids.removeAt(index);\n    ids.insert(target, item);\n    try {\n      await _repository.reorder(ids);\n      if (!mounted) return;\n      _message('Ordem atualizada. A escala futura foi recalculada.');\n      await _refresh();\n    } catch (error) {\n      if (mounted) _message(_errorText(error), error: true);\n    }\n  }\n\n  Future<void> _editRotationMember(\n    _WeeklyOfficerData data,\n    Map<String, dynamic> row,\n  ) async {\n    final memberId = row['member_id']?.toString() ?? '';\n    final member = data.memberById[memberId];\n    bool enabled = row['enabled'] != false;\n    bool forceIncluded = row['force_included'] == true;\n    String availability = row['availability_status']?.toString() ?? 'active';\n    final notes = TextEditingController(text: row['notes']?.toString() ?? '');\n    bool saving = false;\n\n    final saved = await showDialog<bool>(\n      context: context,\n      builder: (dialogContext) => StatefulBuilder(\n        builder: (context, setDialogState) => AlertDialog(\n          title: Text(WeeklyOfficerRules.displayMember(member)),\n          content: SizedBox(\n            width: 480,\n            child: Column(\n              mainAxisSize: MainAxisSize.min,\n              children: [\n                SwitchListTile(\n                  contentPadding: EdgeInsets.zero,\n                  title: const Text('Incluído na rotação'),\n                  value: enabled,\n                  onChanged: saving\n                      ? null\n                      : (value) => setDialogState(() => enabled = value),\n                ),\n                DropdownButtonFormField<String>(\n                  initialValue: availability,\n                  decoration: const InputDecoration(labelText: 'Disponibilidade'),\n                  items: const [\n                    DropdownMenuItem(value: 'active', child: Text('Ativo')),\n                    DropdownMenuItem(value: 'absent', child: Text('Ausente')),\n                    DropdownMenuItem(value: 'inactive', child: Text('Inativo')),\n                  ],\n                  onChanged: saving\n                      ? null\n                      : (value) {\n                          if (value != null) {\n                            setDialogState(() => availability = value);\n                          }\n                        },\n                ),\n                SwitchListTile(\n                  contentPadding: EdgeInsets.zero,\n                  title: const Text('Inclusão forçada'),\n                  subtitle: const Text(\n                    'Ignora exclusão/indisponibilidade para a escala.',\n                  ),\n                  value: forceIncluded,\n                  onChanged: saving\n                      ? null\n                      : (value) => setDialogState(() => forceIncluded = value),\n                ),\n                TextField(\n                  controller: notes,\n                  decoration: const InputDecoration(labelText: 'Observações'),\n                  minLines: 2,\n                  maxLines: 4,\n                ),\n              ],\n            ),\n          ),\n          actions: [\n            TextButton(\n              onPressed: saving ? null : () => Navigator.pop(dialogContext, false),\n              child: const Text('Cancelar'),\n            ),\n            FilledButton(\n              onPressed: saving\n                  ? null\n                  : () async {\n                      setDialogState(() => saving = true);\n                      try {\n                        await _repository.setMemberSettings(\n                          memberId: memberId,\n                          enabled: enabled,\n                          availabilityStatus: availability,\n                          forceIncluded: forceIncluded,\n                          notes: notes.text,\n                        );\n                        if (dialogContext.mounted) {\n                          Navigator.pop(dialogContext, true);\n                        }\n                      } catch (error) {\n                        if (dialogContext.mounted) {\n                          ScaffoldMessenger.of(dialogContext).showSnackBar(\n                            SnackBar(content: Text(_errorText(error))),\n                          );\n                          setDialogState(() => saving = false);\n                        }\n                      }\n                    },\n              child: const Text('Guardar'),\n            ),\n          ],\n        ),\n      ),\n    );\n    if (saved == true && mounted) await _refresh();\n  }\n\n  Future<void> _addAbsence(_WeeklyOfficerData data, String memberId) async {\n    String kind = 'vacation';\n    DateTime starts = DateTime.now();\n    DateTime ends = DateTime.now();\n    final notes = TextEditingController();\n    bool saving = false;\n\n    final saved = await showDialog<bool>(\n      context: context,\n      builder: (dialogContext) => StatefulBuilder(\n        builder: (context, setDialogState) => AlertDialog(\n          title: const Text('Férias / ausência'),\n          content: SizedBox(\n            width: 480,\n            child: Column(\n              mainAxisSize: MainAxisSize.min,\n              children: [\n                DropdownButtonFormField<String>(\n                  initialValue: kind,\n                  decoration: const InputDecoration(labelText: 'Tipo'),\n                  items: const [\n                    DropdownMenuItem(value: 'vacation', child: Text('Férias')),\n                    DropdownMenuItem(value: 'absence', child: Text('Ausência')),\n                  ],\n                  onChanged: saving\n                      ? null\n                      : (value) {\n                          if (value != null) setDialogState(() => kind = value);\n                        },\n                ),\n                const SizedBox(height: 10),\n                _DateInput(\n                  label: 'Início',\n                  value: starts,\n                  onPick: saving\n                      ? null\n                      : (value) => setDialogState(() {\n                            starts = value;\n                            if (ends.isBefore(starts)) ends = starts;\n                          }),\n                ),\n                const SizedBox(height: 10),\n                _DateInput(\n                  label: 'Fim',\n                  value: ends,\n                  onPick: saving\n                      ? null\n                      : (value) => setDialogState(() => ends = value),\n                ),\n                const SizedBox(height: 10),\n                TextField(\n                  controller: notes,\n                  minLines: 2,\n                  maxLines: 4,\n                  decoration: const InputDecoration(labelText: 'Observações'),\n                ),\n              ],\n            ),\n          ),\n          actions: [\n            TextButton(\n              onPressed: saving ? null : () => Navigator.pop(dialogContext, false),\n              child: const Text('Cancelar'),\n            ),\n            FilledButton(\n              onPressed: saving\n                  ? null\n                  : () async {\n                      setDialogState(() => saving = true);\n                      try {\n                        await _repository.saveAbsence(\n                          memberId: memberId,\n                          kind: kind,\n                          startsOn: starts,\n                          endsOn: ends,\n                          notes: notes.text,\n                        );\n                        if (dialogContext.mounted) {\n                          Navigator.pop(dialogContext, true);\n                        }\n                      } catch (error) {\n                        if (dialogContext.mounted) {\n                          ScaffoldMessenger.of(dialogContext).showSnackBar(\n                            SnackBar(content: Text(_errorText(error))),\n                          );\n                          setDialogState(() => saving = false);\n                        }\n                      }\n                    },\n              child: const Text('Guardar'),\n            ),\n          ],\n        ),\n      ),\n    );\n    if (saved == true && mounted) await _refresh();\n  }\n\n  Future<void> _deleteAbsence(Map<String, dynamic> absence) async {\n    final confirmed = await showDialog<bool>(\n      context: context,\n      builder: (dialogContext) => AlertDialog(\n        title: const Text('Remover período?'),\n        content: const Text('A escala futura será recalculada.'),\n        actions: [\n          TextButton(\n            onPressed: () => Navigator.pop(dialogContext, false),\n            child: const Text('Cancelar'),\n          ),\n          FilledButton(\n            onPressed: () => Navigator.pop(dialogContext, true),\n            child: const Text('Remover'),\n          ),\n        ],\n      ),\n    );\n    if (confirmed != true) return;\n    try {\n      await _repository.deleteAbsence(absence['id'].toString());\n      if (!mounted) return;\n      _message('Período removido e escala recalculada.');\n      await _refresh();\n    } catch (error) {\n      if (mounted) _message(_errorText(error), error: true);\n    }\n  }\n\n  Future<void> _openDinnerDialog(\n    _WeeklyOfficerData data, [\n    Map<String, dynamic>? row,\n  ]) async {\n    final regular = row?['dinner_kind']?.toString() == 'regular';\n    DateTime date = row == null\n        ? DateTime.now()\n        : _dateFrom(row['dinner_date']);\n    String? memberId = row?['assigned_member_id']?.toString();\n    bool external = (row?['external_name']?.toString().trim() ?? '').isNotEmpty;\n    final externalName = TextEditingController(\n      text: row?['external_name']?.toString() ?? '',\n    );\n    final dish = TextEditingController(text: row?['dish']?.toString() ?? '');\n    final notes = TextEditingController(text: row?['notes']?.toString() ?? '');\n    String status = row?['status']?.toString() ?? 'planned';\n    if (status == 'closed') status = 'planned';\n    bool saving = false;\n\n    final saved = await showDialog<bool>(\n      context: context,\n      builder: (dialogContext) => StatefulBuilder(\n        builder: (context, setDialogState) => AlertDialog(\n          title: Text(\n            row == null\n                ? 'Novo jantar extraordinário'\n                : regular\n                    ? 'Editar quinta oficial'\n                    : 'Editar jantar extraordinário',\n          ),\n          content: SizedBox(\n            width: 520,\n            child: SingleChildScrollView(\n              child: Column(\n                mainAxisSize: MainAxisSize.min,\n                children: [\n                  _DateInput(\n                    label: 'Data',\n                    value: date,\n                    enabled: !regular,\n                    onPick: saving || regular\n                        ? null\n                        : (value) => setDialogState(() => date = value),\n                  ),\n                  const SizedBox(height: 10),\n                  SwitchListTile(\n                    contentPadding: EdgeInsets.zero,\n                    title: const Text('Pessoa externa'),\n                    value: external,\n                    onChanged: saving\n                        ? null\n                        : (value) => setDialogState(() {\n                              external = value;\n                              if (value) memberId = null;\n                            }),\n                  ),\n                  if (external)\n                    TextField(\n                      controller: externalName,\n                      decoration: const InputDecoration(\n                        labelText: 'Nome do amigo / pessoa externa',\n                      ),\n                    )\n                  else\n                    DropdownButtonFormField<String>(\n                      initialValue: memberId ?? '',\n                      decoration: const InputDecoration(labelText: 'Membro'),\n                      items: [\n                        const DropdownMenuItem(\n                          value: '',\n                          child: Text('Selecionar membro'),\n                        ),\n                        ...data.members.map(\n                          (member) => DropdownMenuItem(\n                            value: member['id'].toString(),\n                            child: Text(WeeklyOfficerRules.displayMember(member)),\n                          ),\n                        ),\n                      ],\n                      onChanged: saving\n                          ? null\n                          : (value) => setDialogState(\n                                () => memberId = value == null || value.isEmpty\n                                    ? null\n                                    : value,\n                              ),\n                    ),\n                  const SizedBox(height: 10),\n                  TextField(\n                    controller: dish,\n                    decoration: const InputDecoration(\n                      labelText: 'Jantar / prato / o que fez',\n                    ),\n                  ),\n                  const SizedBox(height: 10),\n                  TextField(\n                    controller: notes,\n                    minLines: 2,\n                    maxLines: 4,\n                    decoration: const InputDecoration(labelText: 'Observações'),\n                  ),\n                  const SizedBox(height: 10),\n                  DropdownButtonFormField<String>(\n                    initialValue: status,\n                    decoration: const InputDecoration(labelText: 'Estado'),\n                    items: const [\n                      DropdownMenuItem(value: 'planned', child: Text('Planeado')),\n                      DropdownMenuItem(\n                        value: 'completed',\n                        child: Text('Concluído'),\n                      ),\n                      DropdownMenuItem(\n                        value: 'cancelled',\n                        child: Text('Cancelado'),\n                      ),\n                    ],\n                    onChanged: saving\n                        ? null\n                        : (value) {\n                            if (value != null) setDialogState(() => status = value);\n                          },\n                  ),\n                ],\n              ),\n            ),\n          ),\n          actions: [\n            TextButton(\n              onPressed: saving ? null : () => Navigator.pop(dialogContext, false),\n              child: const Text('Cancelar'),\n            ),\n            FilledButton(\n              onPressed: saving\n                  ? null\n                  : () async {\n                      final externalValue = externalName.text.trim();\n                      if ((external && externalValue.isEmpty) ||\n                          (!external && (memberId == null || memberId!.isEmpty))) {\n                        ScaffoldMessenger.of(dialogContext).showSnackBar(\n                          const SnackBar(\n                            content: Text('Indica o membro ou a pessoa externa.'),\n                          ),\n                        );\n                        return;\n                      }\n                      setDialogState(() => saving = true);\n                      try {\n                        await _repository.saveDinner(\n                          dinnerId: row?['id']?.toString(),\n                          date: date,\n                          memberId: external ? null : memberId,\n                          externalName: external ? externalValue : null,\n                          dish: dish.text,\n                          notes: notes.text,\n                          status: status,\n                        );\n                        if (dialogContext.mounted) {\n                          Navigator.pop(dialogContext, true);\n                        }\n                      } catch (error) {\n                        if (dialogContext.mounted) {\n                          ScaffoldMessenger.of(dialogContext).showSnackBar(\n                            SnackBar(content: Text(_errorText(error))),\n                          );\n                          setDialogState(() => saving = false);\n                        }\n                      }\n                    },\n              child: const Text('Guardar'),\n            ),\n          ],\n        ),\n      ),\n    );\n    if (saved == true && mounted) await _refresh();\n  }\n\n  Future<void> _setDinnerClosed(\n    Map<String, dynamic> row,\n    bool closed,\n  ) async {\n    String? note;\n    if (closed) {\n      note = await _askNote(\n        'Fechar quinta-feira',\n        hint: 'Motivo (opcional)',\n        allowEmpty: true,\n      );\n      if (note == null) return;\n    }\n    try {\n      await _repository.setClosed(\n        dinnerId: row['id'].toString(),\n        closed: closed,\n        notes: note,\n      );\n      if (!mounted) return;\n      _message(\n        closed\n            ? 'Quinta marcada como fechada. O membro não perdeu a vez.'\n            : 'Quinta reaberta e escala futura recalculada.',\n      );\n      await _refresh();\n    } catch (error) {\n      if (mounted) _message(_errorText(error), error: true);\n    }\n  }\n\n  Future<void> _requestSwap(\n    _WeeklyOfficerData data,\n    Map<String, dynamic> dinner,\n  ) async {\n    final current = data.currentMemberId;\n    if (current == null) {\n      _message('O teu utilizador ainda não está ligado a um membro.', error: true);\n      return;\n    }\n    final candidates = data.rotation\n        .where(\n          (r) => r['member_id']?.toString() != current && r['enabled'] != false,\n        )\n        .map((r) => r['member_id']?.toString())\n        .whereType<String>()\n        .toList();\n    if (candidates.isEmpty) {\n      _message('Não existem membros disponíveis para pedir troca.', error: true);\n      return;\n    }\n\n    String selected = candidates.first;\n    final note = TextEditingController();\n    bool saving = false;\n    final sent = await showDialog<bool>(\n      context: context,\n      builder: (dialogContext) => StatefulBuilder(\n        builder: (context, setDialogState) => AlertDialog(\n          title: Text('Pedir troca · ${_datePt(dinner['dinner_date'])}'),\n          content: SizedBox(\n            width: 480,\n            child: Column(\n              mainAxisSize: MainAxisSize.min,\n              children: [\n                DropdownButtonFormField<String>(\n                  initialValue: selected,\n                  decoration: const InputDecoration(labelText: 'Pedir a'),\n                  items: candidates\n                      .map(\n                        (id) => DropdownMenuItem(\n                          value: id,\n                          child: Text(\n                            WeeklyOfficerRules.displayMember(data.memberById[id]),\n                          ),\n                        ),\n                      )\n                      .toList(),\n                  onChanged: saving\n                      ? null\n                      : (value) {\n                          if (value != null) setDialogState(() => selected = value);\n                        },\n                ),\n                const SizedBox(height: 10),\n                TextField(\n                  controller: note,\n                  minLines: 2,\n                  maxLines: 4,\n                  decoration: const InputDecoration(labelText: 'Mensagem (opcional)'),\n                ),\n                const SizedBox(height: 8),\n                const Text(\n                  'A troca só altera a escala depois de ser aceite e validada pela Direção.',\n                ),\n              ],\n            ),\n          ),\n          actions: [\n            TextButton(\n              onPressed: saving ? null : () => Navigator.pop(dialogContext, false),\n              child: const Text('Cancelar'),\n            ),\n            FilledButton(\n              onPressed: saving\n                  ? null\n                  : () async {\n                      setDialogState(() => saving = true);\n                      try {\n                        await _repository.requestSwap(\n                          dinnerId: dinner['id'].toString(),\n                          requestedMemberId: selected,\n                          note: note.text,\n                        );\n                        if (dialogContext.mounted) {\n                          Navigator.pop(dialogContext, true);\n                        }\n                      } catch (error) {\n                        if (dialogContext.mounted) {\n                          ScaffoldMessenger.of(dialogContext).showSnackBar(\n                            SnackBar(content: Text(_errorText(error))),\n                          );\n                          setDialogState(() => saving = false);\n                        }\n                      }\n                    },\n              child: const Text('Enviar pedido'),\n            ),\n          ],\n        ),\n      ),\n    );\n    if (sent == true && mounted) {\n      _message('Pedido de troca enviado.');\n      await _refresh();\n    }\n  }\n\n  Future<void> _respondSwap(Map<String, dynamic> row, bool accept) async {\n    final note = await _askNote(\n      accept ? 'Aceitar pedido' : 'Recusar pedido',\n      hint: 'Mensagem (opcional)',\n      allowEmpty: true,\n    );\n    if (note == null) return;\n    try {\n      await _repository.respondSwap(\n        requestId: row['id'].toString(),\n        accept: accept,\n        note: note,\n      );\n      if (!mounted) return;\n      _message(accept ? 'Pedido aceite. Aguarda alteração pela Direção.' : 'Pedido recusado.');\n      await _refresh();\n    } catch (error) {\n      if (mounted) _message(_errorText(error), error: true);\n    }\n  }\n\n  Future<void> _markSwapApplied(Map<String, dynamic> row) async {\n    final note = await _askNote(\n      'Marcar troca como aplicada',\n      hint: 'Observação da alteração feita na escala (opcional)',\n      allowEmpty: true,\n    );\n    if (note == null) return;\n    try {\n      await _repository.markSwapApplied(\n        requestId: row['id'].toString(),\n        note: note,\n      );\n      if (!mounted) return;\n      _message('Troca marcada como aplicada.');\n      await _refresh();\n    } catch (error) {\n      if (mounted) _message(_errorText(error), error: true);\n    }\n  }\n\n  Future<void> _cancelSwap(Map<String, dynamic> row) async {\n    try {\n      await _repository.cancelSwap(row['id'].toString());\n      if (!mounted) return;\n      _message('Pedido cancelado.');\n      await _refresh();\n    } catch (error) {\n      if (mounted) _message(_errorText(error), error: true);\n    }\n  }\n\n  Future<String?> _askNote(\n    String title, {\n    String hint = 'Observação',\n    bool allowEmpty = false,\n  }) async {\n    final controller = TextEditingController();\n    return showDialog<String>(\n      context: context,\n      builder: (dialogContext) => AlertDialog(\n        title: Text(title),\n        content: TextField(\n          controller: controller,\n          minLines: 2,\n          maxLines: 4,\n          autofocus: true,\n          decoration: InputDecoration(labelText: hint),\n        ),\n        actions: [\n          TextButton(\n            onPressed: () => Navigator.pop(dialogContext),\n            child: const Text('Cancelar'),\n          ),\n          FilledButton(\n            onPressed: () {\n              final value = controller.text.trim();\n              if (!allowEmpty && value.isEmpty) return;\n              Navigator.pop(dialogContext, value);\n            },\n            child: const Text('Confirmar'),\n          ),\n        ],\n      ),\n    );\n  }\n\n  void _message(String text, {bool error = false}) {\n    final messenger = ScaffoldMessenger.of(context);\n    messenger.hideCurrentSnackBar();\n    messenger.showSnackBar(\n      SnackBar(\n        content: Text(text),\n        duration: Duration(seconds: error ? 5 : 3),\n      ),\n    );\n  }\n\n  static String _errorText(Object? error) {\n    if (error is PostgrestException) return error.message;\n    final text = error?.toString() ?? 'Erro desconhecido.';\n    return text.replaceFirst('Exception: ', '').replaceFirst('Bad state: ', '');\n  }\n\n  static DateTime _dateFrom(dynamic raw) {\n    if (raw is DateTime) return raw;\n    return DateTime.tryParse(raw?.toString() ?? '') ?? DateTime(1970);\n  }\n\n  static String _datePt(dynamic raw) {\n    final date = _dateFrom(raw);\n    if (date.year == 1970) return '—';\n    return DateFormat('dd/MM/yyyy', 'pt_PT').format(date);\n  }\n}\n\nclass _WeeklyOfficerData {\n  const _WeeklyOfficerData({\n    required this.members,\n    required this.rotation,\n    required this.dinners,\n    required this.absences,\n    required this.swaps,\n    required this.currentMemberId,\n  });\n\n  factory _WeeklyOfficerData.empty() => const _WeeklyOfficerData(\n        members: [],\n        rotation: [],\n        dinners: [],\n        absences: [],\n        swaps: [],\n        currentMemberId: null,\n      );\n\n  final List<Map<String, dynamic>> members;\n  final List<Map<String, dynamic>> rotation;\n  final List<Map<String, dynamic>> dinners;\n  final List<Map<String, dynamic>> absences;\n  final List<Map<String, dynamic>> swaps;\n  final String? currentMemberId;\n\n  Map<String, Map<String, dynamic>> get memberById => {\n        for (final member in members)\n          if (member['id'] != null) member['id'].toString(): member,\n      };\n\n  Map<String, Map<String, dynamic>> get dinnerById => {\n        for (final dinner in dinners)\n          if (dinner['id'] != null) dinner['id'].toString(): dinner,\n      };\n\n  Map<String, int> get officialCounts {\n    final result = <String, int>{};\n    for (final dinner in dinners) {\n      if (!WeeklyOfficerRules.countsAsOfficialDinner(dinner)) continue;\n      final memberId = dinner['assigned_member_id']?.toString();\n      if (memberId == null) continue;\n      result[memberId] = (result[memberId] ?? 0) + 1;\n    }\n    return result;\n  }\n\n  Map<String, dynamic>? get nextRegularDinner {\n    final today = DateTime.now();\n    final start = DateTime(today.year, today.month, today.day);\n    for (final dinner in dinners) {\n      if (dinner['dinner_kind'] != 'regular' || dinner['status'] != 'planned') {\n        continue;\n      }\n      final date = DateTime.tryParse(dinner['dinner_date']?.toString() ?? '');\n      if (date != null && !date.isBefore(start)) return dinner;\n    }\n    return null;\n  }\n\n  String dinnerResponsible(Map<String, dynamic> dinner) {\n    final external = dinner['external_name']?.toString().trim() ?? '';\n    if (external.isNotEmpty) return external;\n    final memberId = dinner['assigned_member_id']?.toString();\n    return WeeklyOfficerRules.displayMember(\n      memberId == null ? null : memberById[memberId],\n    );\n  }\n}\n\nclass _DateInput extends StatelessWidget {\n  const _DateInput({\n    required this.label,\n    required this.value,\n    required this.onPick,\n    this.enabled = true,\n  });\n\n  final String label;\n  final DateTime value;\n  final ValueChanged<DateTime>? onPick;\n  final bool enabled;\n\n  @override\n  Widget build(BuildContext context) {\n    return InkWell(\n      borderRadius: BorderRadius.circular(12),\n      onTap: !enabled || onPick == null\n          ? null\n          : () async {\n              final picked = await showDatePicker(\n                context: context,\n                initialDate: value,\n                firstDate: DateTime(2020),\n                lastDate: DateTime(2100),\n              );\n              if (picked != null) onPick!(picked);\n            },\n      child: InputDecorator(\n        decoration: InputDecoration(\n          labelText: label,\n          prefixIcon: const Icon(Icons.calendar_month_outlined),\n          enabled: enabled,\n        ),\n        child: Text(DateFormat('dd/MM/yyyy', 'pt_PT').format(value)),\n      ),\n    );\n  }\n}\n\nclass _ErrorState extends StatelessWidget {\n  const _ErrorState({required this.message, required this.onRetry});\n\n  final String message;\n  final Future<void> Function() onRetry;\n\n  @override\n  Widget build(BuildContext context) {\n    return Center(\n      child: Padding(\n        padding: const EdgeInsets.all(24),\n        child: Column(\n          mainAxisSize: MainAxisSize.min,\n          children: [\n            const Icon(Icons.error_outline, size: 44),\n            const SizedBox(height: 12),\n            Text(message, textAlign: TextAlign.center),\n            const SizedBox(height: 12),\n            FilledButton.icon(\n              onPressed: onRetry,\n              icon: const Icon(Icons.refresh),\n              label: const Text('Tentar novamente'),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n", 'apps/mobile/test/weekly_officer_rules_test.dart': "import 'package:flutter_test/flutter_test.dart';\nimport 'package:bob_manager_mobile/core/weekly_officer_rules.dart';\n\nvoid main() {\n  group('WeeklyOfficerRules', () {\n    test('gestão fica limitada a Superadmin, Presidente e Vice-Presidente', () {\n      expect(WeeklyOfficerRules.canManageRole('president'), isTrue);\n      expect(WeeklyOfficerRules.canManageRole('Vice-Presidente'), isTrue);\n      expect(WeeklyOfficerRules.canManageRole('super_admin'), isTrue);\n      expect(WeeklyOfficerRules.canManageRole('Tesoureiro'), isFalse);\n      expect(WeeklyOfficerRules.canManageRole('Membro'), isFalse);\n    });\n\n    test('quinta oficial fechada não conta', () {\n      expect(\n        WeeklyOfficerRules.countsAsOfficialDinner({\n          'dinner_kind': 'regular',\n          'status': 'closed',\n          'assigned_member_id': null,\n        }),\n        isFalse,\n      );\n    });\n\n    test('jantar extraordinário não entra na justiça anual', () {\n      expect(\n        WeeklyOfficerRules.countsAsOfficialDinner({\n          'dinner_kind': 'extraordinary',\n          'status': 'completed',\n          'assigned_member_id': 'member-1',\n        }),\n        isFalse,\n      );\n    });\n\n    test('quinta oficial planeada com membro conta', () {\n      expect(\n        WeeklyOfficerRules.countsAsOfficialDinner({\n          'dinner_kind': 'regular',\n          'status': 'planned',\n          'assigned_member_id': 'member-1',\n        }),\n        isTrue,\n      );\n    });\n\n    test('alcunha tem prioridade no nome visível', () {\n      expect(\n        WeeklyOfficerRules.displayMember({\n          'full_name': 'Israel Sousa',\n          'nickname': 'Lela',\n        }),\n        'Lela',\n      );\n    });\n\n    test('estado aceite explicita que a Direção ainda tem de aplicar', () {\n      expect(\n        WeeklyOfficerRules.swapStatusLabel('accepted'),\n        contains('aguarda Direção'),\n      );\n    });\n  });\n}\n", 'docs/COMMIT12_WEEKLY_OFFICER.md': '# Commit 12 — Oficial da Semana / Escala de Jantares\n\n## Objetivo\n\nCriar um módulo próprio para gerir a escala de jantares do clube, com quintas-feiras oficiais, eventos extraordinários, rotação justa, ausências/férias, trocas entre membros e histórico anual.\n\n## Regras funcionais\n\n- O jantar regular é normalmente à quinta-feira.\n- Jantares fora da quinta-feira são registados manualmente como extraordinários.\n- Ordem base da rotação: Presidente → Vice-Presidente → Sargento de Armas → Tesoureiro → Secretário → Road Captain → restantes membros.\n- Novos membros entram automaticamente no fim da rotação.\n- A justiça anual usa a menor contagem de jantares oficiais; em empate prevalece a ordem da rotação.\n- Uma quinta marcada como fechada não conta e o membro mantém a prioridade para a próxima data elegível.\n- Ausências e férias retiram temporariamente o membro das datas abrangidas e recalculam a escala futura.\n- Presidente, Vice-Presidente e Superadmin podem alterar ordem, disponibilidade, inclusão/exclusão, férias/ausências, responsáveis e jantares extraordinários.\n- Pessoas externas podem ser registadas manualmente com nome, data e descrição do que fizeram.\n- Um membro escalado pode pedir troca a outro membro.\n- O destinatário aceita ou recusa; aceitar não altera automaticamente a escala.\n- Depois da aceitação, a Direção altera a escala e marca o pedido como aplicado.\n\n## Dados\n\nTabelas:\n\n- `weekly_officer_rotation`\n- `weekly_officer_absences`\n- `weekly_dinners`\n- `weekly_officer_swap_requests`\n\nTodas têm `club_id`, RLS e metadados de auditoria adequados ao seu fluxo.\n\n## Segurança\n\n- Leitura da escala/rotação/ausências: membros autenticados do clube.\n- Trocas: apenas intervenientes e gestores da escala.\n- Escrita direta nas tabelas não é concedida ao cliente.\n- Alterações são feitas por RPCs com validação server-side.\n- Nenhum RPC do Commit 12 é executável por `anon`.\n- Helpers internos não são executáveis por `authenticated` quando não são necessários pela app/RLS.\n\n## Notificações\n\nO módulo usa `module_code = weekly_officer` e `action_route = weekly_officer`.\n\nSão emitidas notificações persistentes para:\n\n- pedido de troca;\n- aceitação/recusa de troca;\n- conclusão da troca;\n- atribuição manual de um jantar quando o membro tem perfil associado.\n\nA entrega push reutiliza a infraestrutura do Commit 10, quando existir dispositivo/configuração FCM válida.\n\n## Flutter\n\nNovo módulo `weekly_officer` com quatro separadores:\n\n1. **Escala** — quintas oficiais e extraordinários, responsável, prato/descrição, estado, fechar/reabrir, editar e pedir troca.\n2. **Rotação** — ordem, contador anual, disponibilidade, exclusão/inclusão forçada e períodos de férias/ausência.\n3. **Trocas** — pedidos pendentes, aceitar/recusar/cancelar e conclusão pela Direção.\n4. **Histórico** — contagem simplificada por membro, extraordinários, último e próximo jantar.\n\nSem novos plugins Flutter.\n\n## Geração anual\n\n`ensure_weekly_officer_schedule_v1` gera quintas em falta e recalcula apenas a escala necessária. No ano corrente começa na data atual para não fabricar histórico anterior à adoção do módulo.\n\n## Validação server-side efetuada\n\nTestes transacionais com `ROLLBACK`:\n\n- geração de quintas futuras pela ordem aprovada;\n- quinta fechada: `status=closed`, sem responsável e a vez é preservada;\n- férias/ausência: membro abrangido é ignorado e a escala é recalculada;\n- equidade 2026 com três membros atuais: 7 / 7 / 7 jantares oficiais;\n- consulta de 2025: 0 linhas automáticas criadas, protegendo o histórico passado.\n\nNenhum destes testes deixou jantares ou ausências fictícias na base de dados.\n\n## Migrations\n\n- `20260812085920_rc1_weekly_officer_dinner_roster.sql`\n- `20260812091054_rc1_weekly_officer_security_hardening.sql`\n- `20260812091155_rc1_weekly_officer_history_guard.sql`\n\nAs três migrations já foram aplicadas no projeto Supabase remoto durante a construção do Commit 12 e não devem ser reaplicadas manualmente.\n', 'supabase/migrations/20260812085920_rc1_weekly_officer_dinner_roster.sql': "-- Commit 12 — Oficial da Semana / Escala de Jantares\n\ncreate table if not exists public.weekly_officer_rotation (\n  id uuid primary key default gen_random_uuid(),\n  club_id uuid not null references public.clubs(id) on delete cascade,\n  member_id uuid not null references public.members(id) on delete cascade,\n  rotation_order integer not null,\n  enabled boolean not null default true,\n  availability_status text not null default 'active'\n    check (availability_status in ('active','absent','inactive')),\n  force_included boolean not null default false,\n  joined_rotation_at date not null default current_date,\n  notes text,\n  created_at timestamptz not null default now(),\n  created_by uuid default auth.uid(),\n  updated_at timestamptz not null default now(),\n  updated_by uuid default auth.uid(),\n  unique (club_id, member_id)\n);\n\ncreate index if not exists weekly_officer_rotation_club_order_idx\n  on public.weekly_officer_rotation(club_id, rotation_order);\n\ncreate table if not exists public.weekly_officer_absences (\n  id uuid primary key default gen_random_uuid(),\n  club_id uuid not null references public.clubs(id) on delete cascade,\n  member_id uuid not null references public.members(id) on delete cascade,\n  absence_kind text not null default 'vacation'\n    check (absence_kind in ('vacation','absence')),\n  starts_on date not null,\n  ends_on date not null,\n  notes text,\n  created_at timestamptz not null default now(),\n  created_by uuid default auth.uid(),\n  updated_at timestamptz not null default now(),\n  updated_by uuid default auth.uid(),\n  check (ends_on >= starts_on)\n);\n\ncreate index if not exists weekly_officer_absences_lookup_idx\n  on public.weekly_officer_absences(club_id, member_id, starts_on, ends_on);\n\ncreate table if not exists public.weekly_dinners (\n  id uuid primary key default gen_random_uuid(),\n  club_id uuid not null references public.clubs(id) on delete cascade,\n  dinner_date date not null,\n  dinner_kind text not null default 'regular'\n    check (dinner_kind in ('regular','extraordinary')),\n  status text not null default 'planned'\n    check (status in ('planned','closed','completed','cancelled')),\n  assigned_member_id uuid references public.members(id) on delete set null,\n  external_name text,\n  dish text,\n  notes text,\n  assignment_source text not null default 'auto'\n    check (assignment_source in ('auto','manual','swap','external')),\n  generated boolean not null default false,\n  created_at timestamptz not null default now(),\n  created_by uuid default auth.uid(),\n  updated_at timestamptz not null default now(),\n  updated_by uuid default auth.uid(),\n  unique (club_id, dinner_date, dinner_kind),\n  check (assigned_member_id is null or nullif(btrim(coalesce(external_name,'')),'') is null)\n);\n\ncreate index if not exists weekly_dinners_club_date_idx\n  on public.weekly_dinners(club_id, dinner_date);\ncreate index if not exists weekly_dinners_member_date_idx\n  on public.weekly_dinners(club_id, assigned_member_id, dinner_date);\n\ncreate table if not exists public.weekly_officer_swap_requests (\n  id uuid primary key default gen_random_uuid(),\n  club_id uuid not null references public.clubs(id) on delete cascade,\n  dinner_id uuid not null references public.weekly_dinners(id) on delete cascade,\n  requester_member_id uuid not null references public.members(id) on delete cascade,\n  requested_member_id uuid not null references public.members(id) on delete cascade,\n  status text not null default 'pending'\n    check (status in ('pending','accepted','rejected','applied','cancelled')),\n  requester_note text,\n  response_note text,\n  manager_note text,\n  responded_at timestamptz,\n  responded_by uuid,\n  applied_at timestamptz,\n  applied_by uuid,\n  created_at timestamptz not null default now(),\n  created_by uuid default auth.uid(),\n  updated_at timestamptz not null default now(),\n  updated_by uuid default auth.uid(),\n  check (requester_member_id <> requested_member_id)\n);\n\ncreate unique index if not exists weekly_officer_swap_pending_unique\n  on public.weekly_officer_swap_requests(dinner_id, requester_member_id, requested_member_id)\n  where status in ('pending','accepted');\n\n-- Fixed-role management rule approved for this module.\ncreate or replace function public.can_manage_weekly_officer_v1(target_club uuid)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path=public\nas $$\n  select (select auth.uid()) is not null\n    and exists (\n      select 1\n      from public.club_memberships cm\n      where cm.club_id=target_club\n        and cm.profile_id=(select auth.uid())\n        and cm.active=true\n        and cm.access_role in ('super_admin','president','vice_president')\n    );\n$$;\n\ncreate or replace function public.current_weekly_officer_member_v1(target_club uuid)\nreturns uuid\nlanguage sql\nstable\nsecurity definer\nset search_path=public\nas $$\n  select m.id\n  from public.members m\n  where m.club_id=target_club\n    and m.profile_id=(select auth.uid())\n  limit 1;\n$$;\n\ncreate or replace function public.weekly_officer_member_available_v1(\n  target_club uuid,\n  p_member uuid,\n  p_date date\n)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path=public\nas $$\n  select exists (\n    select 1\n    from public.weekly_officer_rotation r\n    join public.members m on m.id=r.member_id and m.club_id=r.club_id\n    where r.club_id=target_club\n      and r.member_id=p_member\n      and (\n        r.force_included=true\n        or (\n          r.enabled=true\n          and r.availability_status='active'\n          and m.status::text not in ('suspended','former','deceased')\n          and not exists (\n            select 1\n            from public.weekly_officer_absences a\n            where a.club_id=target_club\n              and a.member_id=p_member\n              and p_date between a.starts_on and a.ends_on\n          )\n        )\n      )\n  );\n$$;\n\ncreate or replace function public.weekly_officer_notify_member_v1(\n  target_club uuid,\n  p_member uuid,\n  p_title text,\n  p_body text,\n  p_entity_type text,\n  p_entity_id uuid\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_profile uuid;\n  v_in_app boolean;\nbegin\n  select m.profile_id into v_profile\n  from public.members m\n  where m.id=p_member and m.club_id=target_club;\n\n  if v_profile is null then return; end if;\n\n  select np.in_app_enabled into v_in_app\n  from public.notification_preferences np\n  where np.club_id=target_club\n    and np.profile_id=v_profile\n    and np.module_code='weekly_officer';\n\n  if coalesce(v_in_app,true)=false then return; end if;\n\n  insert into public.notifications(\n    club_id,profile_id,title,body,notification_type,module_code,priority,\n    entity_type,entity_id,action_route,metadata\n  ) values (\n    target_club,v_profile,p_title,p_body,'info','weekly_officer','normal',\n    p_entity_type,p_entity_id,'weekly_officer',jsonb_build_object('module_code','weekly_officer')\n  );\nend;\n$$;\n\n-- Internal rebuild: keeps manual/swap assignments, recalculates only automatic future rows.\ncreate or replace function public.rebuild_weekly_officer_schedule_internal_v1(\n  target_club uuid,\n  p_from_date date,\n  p_through_date date\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_dinner record;\n  v_member uuid;\n  v_year int;\nbegin\n  if p_through_date < p_from_date then return; end if;\n\n  update public.weekly_dinners d\n  set assigned_member_id=null,\n      updated_at=now(),\n      updated_by=coalesce((select auth.uid()),updated_by)\n  where d.club_id=target_club\n    and d.dinner_kind='regular'\n    and d.status='planned'\n    and d.assignment_source='auto'\n    and d.dinner_date between p_from_date and p_through_date;\n\n  for v_dinner in\n    select d.id,d.dinner_date\n    from public.weekly_dinners d\n    where d.club_id=target_club\n      and d.dinner_kind='regular'\n      and d.status='planned'\n      and d.assignment_source='auto'\n      and d.assigned_member_id is null\n      and d.dinner_date between p_from_date and p_through_date\n    order by d.dinner_date\n  loop\n    v_year:=extract(year from v_dinner.dinner_date)::int;\n\n    select r.member_id into v_member\n    from public.weekly_officer_rotation r\n    where r.club_id=target_club\n      and public.weekly_officer_member_available_v1(\n        target_club,r.member_id,v_dinner.dinner_date\n      )\n    order by (\n      select count(*)\n      from public.weekly_dinners x\n      where x.club_id=target_club\n        and x.dinner_kind='regular'\n        and x.status in ('planned','completed')\n        and x.assigned_member_id=r.member_id\n        and extract(year from x.dinner_date)::int=v_year\n    ) asc,\n    r.rotation_order asc,\n    r.joined_rotation_at asc,\n    r.member_id\n    limit 1;\n\n    if v_member is not null then\n      update public.weekly_dinners\n      set assigned_member_id=v_member,\n          assignment_source='auto',\n          updated_at=now(),\n          updated_by=coalesce((select auth.uid()),updated_by)\n      where id=v_dinner.id;\n    end if;\n  end loop;\nend;\n$$;\n\ncreate or replace function public.rebuild_weekly_officer_future_internal_v1(\n  target_club uuid,\n  p_from_date date\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_year record;\n  v_start date;\n  v_end date;\nbegin\n  for v_year in\n    select distinct extract(year from d.dinner_date)::int as year_no\n    from public.weekly_dinners d\n    where d.club_id=target_club\n      and d.dinner_kind='regular'\n      and d.dinner_date>=p_from_date\n    order by 1\n  loop\n    v_start:=greatest(p_from_date,make_date(v_year.year_no,1,1));\n    v_end:=make_date(v_year.year_no,12,31);\n    perform public.rebuild_weekly_officer_schedule_internal_v1(\n      target_club,v_start,v_end\n    );\n  end loop;\nend;\n$$;\n\ncreate or replace function public.ensure_weekly_officer_schedule_v1(\n  target_club uuid,\n  p_year integer\n)\nreturns integer\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_start date;\n  v_end date;\n  v_first date;\n  v_inserted integer:=0;\nbegin\n  if (select auth.uid()) is null or not public.has_club_access(target_club) then\n    raise exception 'Sem acesso ao clube.';\n  end if;\n  if p_year<2020 or p_year>2100 then raise exception 'Ano inválido.'; end if;\n\n  v_start:=make_date(p_year,1,1);\n  v_end:=make_date(p_year,12,31);\n  if p_year=extract(year from current_date)::int then\n    v_start:=greatest(v_start,current_date);\n  end if;\n\n  v_first:=v_start + ((4-extract(dow from v_start)::int+7)%7);\n\n  insert into public.weekly_dinners(\n    club_id,dinner_date,dinner_kind,status,assignment_source,generated\n  )\n  select target_club,gs::date,'regular','planned','auto',true\n  from generate_series(v_first::timestamp,v_end::timestamp,interval '7 day') gs\n  on conflict (club_id,dinner_date,dinner_kind) do nothing;\n  get diagnostics v_inserted=row_count;\n\n  perform public.rebuild_weekly_officer_schedule_internal_v1(\n    target_club,v_first,v_end\n  );\n  return v_inserted;\nend;\n$$;\n\ncreate or replace function public.set_weekly_officer_member_v1(\n  target_club uuid,\n  p_member uuid,\n  p_enabled boolean,\n  p_availability_status text,\n  p_force_included boolean,\n  p_notes text default null\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_old jsonb;\n  v_new jsonb;\n  v_order integer;\nbegin\n  if not public.can_manage_weekly_officer_v1(target_club) then\n    raise exception 'Apenas Presidente, Vice-Presidente ou Superadmin podem gerir a escala.';\n  end if;\n  if p_availability_status not in ('active','absent','inactive') then\n    raise exception 'Estado de disponibilidade inválido.';\n  end if;\n  if not exists(select 1 from public.members where id=p_member and club_id=target_club) then\n    raise exception 'Membro inválido.';\n  end if;\n\n  select to_jsonb(r) into v_old\n  from public.weekly_officer_rotation r\n  where r.club_id=target_club and r.member_id=p_member;\n\n  if v_old is null then\n    select coalesce(max(rotation_order),0)+10 into v_order\n    from public.weekly_officer_rotation where club_id=target_club;\n    insert into public.weekly_officer_rotation(\n      club_id,member_id,rotation_order,enabled,availability_status,\n      force_included,notes\n    ) values (\n      target_club,p_member,v_order,coalesce(p_enabled,true),p_availability_status,\n      coalesce(p_force_included,false),nullif(btrim(coalesce(p_notes,'')),'')\n    );\n  else\n    update public.weekly_officer_rotation\n    set enabled=coalesce(p_enabled,enabled),\n        availability_status=p_availability_status,\n        force_included=coalesce(p_force_included,force_included),\n        notes=nullif(btrim(coalesce(p_notes,'')),''),\n        updated_at=now(),updated_by=(select auth.uid())\n    where club_id=target_club and member_id=p_member;\n  end if;\n\n  select to_jsonb(r) into v_new\n  from public.weekly_officer_rotation r\n  where r.club_id=target_club and r.member_id=p_member;\n\n  perform public.audit_event(\n    target_club,'weekly_officer_member_updated','weekly_officer_rotation',\n    p_member::text,v_old,v_new,null\n  );\n  perform public.rebuild_weekly_officer_future_internal_v1(target_club,current_date);\nend;\n$$;\n\ncreate or replace function public.reorder_weekly_officer_v1(\n  target_club uuid,\n  p_member_ids uuid[]\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_expected int;\n  v_supplied int;\n  v_distinct int;\n  v_member uuid;\n  v_index int:=0;\nbegin\n  if not public.can_manage_weekly_officer_v1(target_club) then\n    raise exception 'Apenas Presidente, Vice-Presidente ou Superadmin podem alterar a ordem.';\n  end if;\n  select count(*) into v_expected from public.weekly_officer_rotation where club_id=target_club;\n  v_supplied:=coalesce(array_length(p_member_ids,1),0);\n  select count(distinct x) into v_distinct from unnest(coalesce(p_member_ids,array[]::uuid[])) x;\n  if v_supplied<>v_expected or v_distinct<>v_expected then\n    raise exception 'A lista deve conter todos os membros da rotação uma única vez.';\n  end if;\n  if exists(\n    select 1 from unnest(p_member_ids) x\n    where not exists(\n      select 1 from public.weekly_officer_rotation r\n      where r.club_id=target_club and r.member_id=x\n    )\n  ) then raise exception 'A lista contém um membro inválido.'; end if;\n\n  foreach v_member in array p_member_ids loop\n    v_index:=v_index+1;\n    update public.weekly_officer_rotation\n    set rotation_order=v_index*10,updated_at=now(),updated_by=(select auth.uid())\n    where club_id=target_club and member_id=v_member;\n  end loop;\n\n  perform public.audit_event(\n    target_club,'weekly_officer_rotation_reordered','weekly_officer_rotation',\n    target_club::text,null,jsonb_build_object('member_ids',p_member_ids),null\n  );\n  perform public.rebuild_weekly_officer_future_internal_v1(target_club,current_date);\nend;\n$$;\n\ncreate or replace function public.save_weekly_officer_absence_v1(\n  target_club uuid,\n  p_absence uuid,\n  p_member uuid,\n  p_absence_kind text,\n  p_starts_on date,\n  p_ends_on date,\n  p_notes text default null\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_id uuid;\n  v_old jsonb;\n  v_new jsonb;\nbegin\n  if not public.can_manage_weekly_officer_v1(target_club) then\n    raise exception 'Sem autorização para gerir ausências/férias.';\n  end if;\n  if p_absence_kind not in ('vacation','absence') then raise exception 'Tipo inválido.'; end if;\n  if p_starts_on is null or p_ends_on is null or p_ends_on<p_starts_on then\n    raise exception 'Intervalo de datas inválido.';\n  end if;\n  if not exists(select 1 from public.members where id=p_member and club_id=target_club) then\n    raise exception 'Membro inválido.';\n  end if;\n\n  if p_absence is null then\n    insert into public.weekly_officer_absences(\n      club_id,member_id,absence_kind,starts_on,ends_on,notes\n    ) values (\n      target_club,p_member,p_absence_kind,p_starts_on,p_ends_on,\n      nullif(btrim(coalesce(p_notes,'')),'')\n    ) returning id into v_id;\n  else\n    select to_jsonb(a) into v_old from public.weekly_officer_absences a\n    where a.id=p_absence and a.club_id=target_club;\n    if v_old is null then raise exception 'Ausência/férias não encontrada.'; end if;\n    update public.weekly_officer_absences\n    set member_id=p_member,absence_kind=p_absence_kind,\n        starts_on=p_starts_on,ends_on=p_ends_on,\n        notes=nullif(btrim(coalesce(p_notes,'')),''),\n        updated_at=now(),updated_by=(select auth.uid())\n    where id=p_absence and club_id=target_club\n    returning id into v_id;\n  end if;\n\n  select to_jsonb(a) into v_new from public.weekly_officer_absences a where a.id=v_id;\n  perform public.audit_event(\n    target_club,'weekly_officer_absence_saved','weekly_officer_absence',\n    v_id::text,v_old,v_new,null\n  );\n  perform public.rebuild_weekly_officer_future_internal_v1(\n    target_club,greatest(current_date,p_starts_on)\n  );\n  return v_id;\nend;\n$$;\n\ncreate or replace function public.delete_weekly_officer_absence_v1(\n  target_club uuid,\n  p_absence uuid\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_old jsonb;\n  v_start date;\nbegin\n  if not public.can_manage_weekly_officer_v1(target_club) then\n    raise exception 'Sem autorização para gerir ausências/férias.';\n  end if;\n  select to_jsonb(a),a.starts_on into v_old,v_start\n  from public.weekly_officer_absences a\n  where a.id=p_absence and a.club_id=target_club;\n  if v_old is null then raise exception 'Ausência/férias não encontrada.'; end if;\n  delete from public.weekly_officer_absences where id=p_absence and club_id=target_club;\n  perform public.audit_event(\n    target_club,'weekly_officer_absence_deleted','weekly_officer_absence',\n    p_absence::text,v_old,null,null\n  );\n  perform public.rebuild_weekly_officer_future_internal_v1(\n    target_club,greatest(current_date,v_start)\n  );\nend;\n$$;\n\ncreate or replace function public.save_weekly_dinner_v1(\n  target_club uuid,\n  p_dinner uuid,\n  p_date date,\n  p_assigned_member uuid default null,\n  p_external_name text default null,\n  p_dish text default null,\n  p_notes text default null,\n  p_status text default 'planned'\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_id uuid;\n  v_old public.weekly_dinners%rowtype;\n  v_new public.weekly_dinners%rowtype;\n  v_kind text;\n  v_source text;\n  v_rebuild_from date;\nbegin\n  if not public.can_manage_weekly_officer_v1(target_club) then\n    raise exception 'Apenas Presidente, Vice-Presidente ou Superadmin podem alterar a escala.';\n  end if;\n  if p_status not in ('planned','completed','cancelled') then\n    raise exception 'Estado inválido para edição.';\n  end if;\n  if p_assigned_member is not null and not exists(\n    select 1 from public.members where id=p_assigned_member and club_id=target_club\n  ) then raise exception 'Membro inválido.'; end if;\n  if p_assigned_member is not null and nullif(btrim(coalesce(p_external_name,'')),'') is not null then\n    raise exception 'Escolhe um membro ou um externo, não ambos.';\n  end if;\n\n  if p_dinner is null then\n    if p_date is null then raise exception 'Indica a data.'; end if;\n    v_kind:='extraordinary';\n    v_source:=case when nullif(btrim(coalesce(p_external_name,'')),'') is not null then 'external' else 'manual' end;\n    insert into public.weekly_dinners(\n      club_id,dinner_date,dinner_kind,status,assigned_member_id,external_name,\n      dish,notes,assignment_source,generated\n    ) values (\n      target_club,p_date,'extraordinary',p_status,p_assigned_member,\n      nullif(btrim(coalesce(p_external_name,'')),''),\n      nullif(btrim(coalesce(p_dish,'')),''),nullif(btrim(coalesce(p_notes,'')),''),\n      v_source,false\n    ) returning id into v_id;\n  else\n    select * into v_old from public.weekly_dinners\n    where id=p_dinner and club_id=target_club for update;\n    if not found then raise exception 'Jantar não encontrado.'; end if;\n    v_kind:=v_old.dinner_kind;\n    if v_kind='regular' and p_date is distinct from v_old.dinner_date then\n      raise exception 'A data de uma quinta oficial não pode ser alterada.';\n    end if;\n    v_source:=case\n      when nullif(btrim(coalesce(p_external_name,'')),'') is not null then 'external'\n      when p_assigned_member is distinct from v_old.assigned_member_id then 'manual'\n      else v_old.assignment_source\n    end;\n    update public.weekly_dinners\n    set dinner_date=case when v_kind='regular' then dinner_date else p_date end,\n        status=p_status,\n        assigned_member_id=p_assigned_member,\n        external_name=nullif(btrim(coalesce(p_external_name,'')),''),\n        dish=nullif(btrim(coalesce(p_dish,'')),''),\n        notes=nullif(btrim(coalesce(p_notes,'')),''),\n        assignment_source=v_source,\n        updated_at=now(),updated_by=(select auth.uid())\n    where id=p_dinner\n    returning * into v_new;\n    v_id:=p_dinner;\n  end if;\n\n  select * into v_new from public.weekly_dinners where id=v_id;\n  perform public.audit_event(\n    target_club,'weekly_dinner_saved','weekly_dinner',v_id::text,\n    case when p_dinner is null then null else to_jsonb(v_old) end,to_jsonb(v_new),null\n  );\n\n  if v_kind='regular' then\n    v_rebuild_from:=greatest(current_date,v_new.dinner_date+1);\n    perform public.rebuild_weekly_officer_future_internal_v1(target_club,v_rebuild_from);\n  end if;\n\n  if v_new.assigned_member_id is not null\n     and (p_dinner is null or v_old.assigned_member_id is distinct from v_new.assigned_member_id) then\n    perform public.weekly_officer_notify_member_v1(\n      target_club,v_new.assigned_member_id,\n      'Alteração na escala de jantares',\n      'Ficaste escalado para o jantar de '||to_char(v_new.dinner_date,'DD/MM/YYYY')||'.',\n      'weekly_dinner',v_id\n    );\n  end if;\n\n  return v_id;\nend;\n$$;\n\ncreate or replace function public.set_weekly_dinner_closed_v1(\n  target_club uuid,\n  p_dinner uuid,\n  p_closed boolean,\n  p_notes text default null\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_old public.weekly_dinners%rowtype;\n  v_new public.weekly_dinners%rowtype;\nbegin\n  if not public.can_manage_weekly_officer_v1(target_club) then\n    raise exception 'Sem autorização para fechar/reabrir uma quinta-feira.';\n  end if;\n  select * into v_old from public.weekly_dinners\n  where id=p_dinner and club_id=target_club and dinner_kind='regular' for update;\n  if not found then raise exception 'Quinta-feira oficial não encontrada.'; end if;\n\n  update public.weekly_dinners\n  set status=case when p_closed then 'closed' else 'planned' end,\n      assigned_member_id=case when p_closed then null else assigned_member_id end,\n      assignment_source=case when p_closed then 'auto' else 'auto' end,\n      notes=coalesce(nullif(btrim(coalesce(p_notes,'')),''),notes),\n      updated_at=now(),updated_by=(select auth.uid())\n  where id=p_dinner\n  returning * into v_new;\n\n  perform public.audit_event(\n    target_club,\n    case when p_closed then 'weekly_dinner_closed' else 'weekly_dinner_reopened' end,\n    'weekly_dinner',p_dinner::text,to_jsonb(v_old),to_jsonb(v_new),p_notes\n  );\n  perform public.rebuild_weekly_officer_future_internal_v1(\n    target_club,greatest(current_date,v_old.dinner_date)\n  );\nend;\n$$;\n\ncreate or replace function public.request_weekly_officer_swap_v1(\n  target_club uuid,\n  p_dinner uuid,\n  p_requested_member uuid,\n  p_note text default null\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_requester uuid;\n  v_id uuid;\n  v_date date;\n  v_requester_name text;\nbegin\n  if (select auth.uid()) is null or not public.has_club_access(target_club) then\n    raise exception 'Sem acesso ao clube.';\n  end if;\n  v_requester:=public.current_weekly_officer_member_v1(target_club);\n  if v_requester is null then raise exception 'O teu utilizador não está ligado a um membro.'; end if;\n  if p_requested_member=v_requester then raise exception 'Não podes pedir troca contigo próprio.'; end if;\n  if not exists(select 1 from public.members where id=p_requested_member and club_id=target_club) then\n    raise exception 'Membro pedido inválido.';\n  end if;\n\n  select d.dinner_date into v_date\n  from public.weekly_dinners d\n  where d.id=p_dinner and d.club_id=target_club\n    and d.dinner_kind='regular' and d.status='planned'\n    and d.assigned_member_id=v_requester\n    and d.dinner_date>=current_date;\n  if v_date is null then raise exception 'Só podes pedir troca do teu próprio jantar futuro.'; end if;\n\n  insert into public.weekly_officer_swap_requests(\n    club_id,dinner_id,requester_member_id,requested_member_id,requester_note\n  ) values (\n    target_club,p_dinner,v_requester,p_requested_member,\n    nullif(btrim(coalesce(p_note,'')),'')\n  ) returning id into v_id;\n\n  select coalesce(nullif(m.nickname,''),m.full_name) into v_requester_name\n  from public.members m where m.id=v_requester;\n  perform public.weekly_officer_notify_member_v1(\n    target_club,p_requested_member,'Pedido de troca de jantar',\n    coalesce(v_requester_name,'Um membro')||' pediu troca para '||to_char(v_date,'DD/MM/YYYY')||'.',\n    'weekly_officer_swap',v_id\n  );\n  perform public.audit_event(\n    target_club,'weekly_officer_swap_requested','weekly_officer_swap',\n    v_id::text,null,jsonb_build_object('dinner_id',p_dinner,'requested_member_id',p_requested_member),null\n  );\n  return v_id;\nend;\n$$;\n\ncreate or replace function public.respond_weekly_officer_swap_v1(\n  target_club uuid,\n  p_request uuid,\n  p_accept boolean,\n  p_note text default null\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_member uuid;\n  v_row public.weekly_officer_swap_requests%rowtype;\n  v_status text;\n  v_responder_name text;\nbegin\n  v_member:=public.current_weekly_officer_member_v1(target_club);\n  if v_member is null then raise exception 'O teu utilizador não está ligado a um membro.'; end if;\n  select * into v_row from public.weekly_officer_swap_requests\n  where id=p_request and club_id=target_club and status='pending' for update;\n  if not found then raise exception 'Pedido de troca pendente não encontrado.'; end if;\n  if v_row.requested_member_id<>v_member then raise exception 'Este pedido não te é dirigido.'; end if;\n\n  v_status:=case when p_accept then 'accepted' else 'rejected' end;\n  update public.weekly_officer_swap_requests\n  set status=v_status,response_note=nullif(btrim(coalesce(p_note,'')),''),\n      responded_at=now(),responded_by=(select auth.uid()),\n      updated_at=now(),updated_by=(select auth.uid())\n  where id=p_request;\n\n  select coalesce(nullif(m.nickname,''),m.full_name) into v_responder_name\n  from public.members m where m.id=v_member;\n  perform public.weekly_officer_notify_member_v1(\n    target_club,v_row.requester_member_id,\n    case when p_accept then 'Troca aceite' else 'Troca recusada' end,\n    coalesce(v_responder_name,'O membro')||\n      case when p_accept then ' aceitou o pedido. A alteração aguarda Presidente/Vice-Presidente.' else ' recusou o pedido.' end,\n    'weekly_officer_swap',p_request\n  );\nend;\n$$;\n\ncreate or replace function public.mark_weekly_officer_swap_applied_v1(\n  target_club uuid,\n  p_request uuid,\n  p_note text default null\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_row public.weekly_officer_swap_requests%rowtype;\nbegin\n  if not public.can_manage_weekly_officer_v1(target_club) then\n    raise exception 'Sem autorização para concluir a troca.';\n  end if;\n  select * into v_row from public.weekly_officer_swap_requests\n  where id=p_request and club_id=target_club and status='accepted' for update;\n  if not found then raise exception 'Pedido aceite não encontrado.'; end if;\n\n  update public.weekly_officer_swap_requests\n  set status='applied',manager_note=nullif(btrim(coalesce(p_note,'')),''),\n      applied_at=now(),applied_by=(select auth.uid()),\n      updated_at=now(),updated_by=(select auth.uid())\n  where id=p_request;\n\n  perform public.weekly_officer_notify_member_v1(\n    target_club,v_row.requester_member_id,'Troca concluída',\n    'A Direção marcou o pedido de troca como aplicado na escala.',\n    'weekly_officer_swap',p_request\n  );\n  perform public.weekly_officer_notify_member_v1(\n    target_club,v_row.requested_member_id,'Troca concluída',\n    'A Direção marcou o pedido de troca como aplicado na escala.',\n    'weekly_officer_swap',p_request\n  );\nend;\n$$;\n\ncreate or replace function public.cancel_weekly_officer_swap_v1(\n  target_club uuid,\n  p_request uuid\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_member uuid;\n  v_row public.weekly_officer_swap_requests%rowtype;\nbegin\n  v_member:=public.current_weekly_officer_member_v1(target_club);\n  select * into v_row from public.weekly_officer_swap_requests\n  where id=p_request and club_id=target_club and status='pending' for update;\n  if not found then raise exception 'Pedido pendente não encontrado.'; end if;\n  if v_member is distinct from v_row.requester_member_id\n     and not public.can_manage_weekly_officer_v1(target_club) then\n    raise exception 'Sem autorização para cancelar este pedido.';\n  end if;\n  update public.weekly_officer_swap_requests\n  set status='cancelled',updated_at=now(),updated_by=(select auth.uid())\n  where id=p_request;\nend;\n$$;\n\n-- New members are appended to the end automatically. Existing order is never changed by this trigger.\ncreate or replace function public.weekly_officer_member_append_trigger_v1()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path=public\nas $$\ndeclare\n  v_order integer;\nbegin\n  if not exists(\n    select 1 from public.weekly_officer_rotation r\n    where r.club_id=new.club_id and r.member_id=new.id\n  ) then\n    select coalesce(max(r.rotation_order),0)+10 into v_order\n    from public.weekly_officer_rotation r where r.club_id=new.club_id;\n    insert into public.weekly_officer_rotation(club_id,member_id,rotation_order)\n    values(new.club_id,new.id,v_order)\n    on conflict (club_id,member_id) do nothing;\n  end if;\n  return new;\nend;\n$$;\n\ndrop trigger if exists trg_weekly_officer_member_append on public.members;\ncreate trigger trg_weekly_officer_member_append\nafter insert on public.members\nfor each row execute function public.weekly_officer_member_append_trigger_v1();\n\n-- Seed existing members with the approved initial role priority, then remaining members.\nwith ranked as (\n  select m.club_id,m.id as member_id,\n    row_number() over(\n      partition by m.club_id\n      order by\n        case\n          when lower(trim(coalesce(m.primary_role,''))) in ('presidente','president') then 10\n          when lower(trim(coalesce(m.primary_role,''))) in ('vice-presidente','vice presidente','vice-president','vice president') then 20\n          when lower(trim(coalesce(m.primary_role,''))) in ('sargento de armas','sergeant at arms') then 30\n          when lower(trim(coalesce(m.primary_role,''))) in ('tesoureiro','treasurer') then 40\n          when lower(trim(coalesce(m.primary_role,''))) in ('secretário','secretario','secretary') then 50\n          when lower(trim(coalesce(m.primary_role,''))) in ('road captain') then 60\n          else 1000\n        end,\n        m.member_number nulls last,m.created_at,m.id\n    )::int as rn\n  from public.members m\n)\ninsert into public.weekly_officer_rotation(club_id,member_id,rotation_order)\nselect club_id,member_id,rn*10 from ranked\non conflict (club_id,member_id) do nothing;\n\n-- RLS: schedule/rotation visible to club members; writes only through RPCs.\nalter table public.weekly_officer_rotation enable row level security;\nalter table public.weekly_officer_absences enable row level security;\nalter table public.weekly_dinners enable row level security;\nalter table public.weekly_officer_swap_requests enable row level security;\n\ndrop policy if exists weekly_officer_rotation_select on public.weekly_officer_rotation;\ncreate policy weekly_officer_rotation_select on public.weekly_officer_rotation\nfor select to authenticated using (public.has_club_access(club_id));\n\ndrop policy if exists weekly_officer_absences_select on public.weekly_officer_absences;\ncreate policy weekly_officer_absences_select on public.weekly_officer_absences\nfor select to authenticated using (public.has_club_access(club_id));\n\ndrop policy if exists weekly_dinners_select on public.weekly_dinners;\ncreate policy weekly_dinners_select on public.weekly_dinners\nfor select to authenticated using (public.has_club_access(club_id));\n\ndrop policy if exists weekly_officer_swaps_select on public.weekly_officer_swap_requests;\ncreate policy weekly_officer_swaps_select on public.weekly_officer_swap_requests\nfor select to authenticated using (\n  public.can_manage_weekly_officer_v1(club_id)\n  or requester_member_id=public.current_weekly_officer_member_v1(club_id)\n  or requested_member_id=public.current_weekly_officer_member_v1(club_id)\n);\n\n-- No direct client writes.\nrevoke all on public.weekly_officer_rotation from anon,authenticated;\nrevoke all on public.weekly_officer_absences from anon,authenticated;\nrevoke all on public.weekly_dinners from anon,authenticated;\nrevoke all on public.weekly_officer_swap_requests from anon,authenticated;\ngrant select on public.weekly_officer_rotation to authenticated;\ngrant select on public.weekly_officer_absences to authenticated;\ngrant select on public.weekly_dinners to authenticated;\ngrant select on public.weekly_officer_swap_requests to authenticated;\n\n-- RPC grants.\nrevoke execute on function public.can_manage_weekly_officer_v1(uuid) from public,anon;\nrevoke execute on function public.current_weekly_officer_member_v1(uuid) from public,anon;\nrevoke execute on function public.weekly_officer_member_available_v1(uuid,uuid,date) from public,anon;\nrevoke execute on function public.ensure_weekly_officer_schedule_v1(uuid,integer) from public,anon;\nrevoke execute on function public.set_weekly_officer_member_v1(uuid,uuid,boolean,text,boolean,text) from public,anon;\nrevoke execute on function public.reorder_weekly_officer_v1(uuid,uuid[]) from public,anon;\nrevoke execute on function public.save_weekly_officer_absence_v1(uuid,uuid,uuid,text,date,date,text) from public,anon;\nrevoke execute on function public.delete_weekly_officer_absence_v1(uuid,uuid) from public,anon;\nrevoke execute on function public.save_weekly_dinner_v1(uuid,uuid,date,uuid,text,text,text,text) from public,anon;\nrevoke execute on function public.set_weekly_dinner_closed_v1(uuid,uuid,boolean,text) from public,anon;\nrevoke execute on function public.request_weekly_officer_swap_v1(uuid,uuid,uuid,text) from public,anon;\nrevoke execute on function public.respond_weekly_officer_swap_v1(uuid,uuid,boolean,text) from public,anon;\nrevoke execute on function public.mark_weekly_officer_swap_applied_v1(uuid,uuid,text) from public,anon;\nrevoke execute on function public.cancel_weekly_officer_swap_v1(uuid,uuid) from public,anon;\n\ngrant execute on function public.can_manage_weekly_officer_v1(uuid) to authenticated;\ngrant execute on function public.current_weekly_officer_member_v1(uuid) to authenticated;\ngrant execute on function public.weekly_officer_member_available_v1(uuid,uuid,date) to authenticated;\ngrant execute on function public.ensure_weekly_officer_schedule_v1(uuid,integer) to authenticated;\ngrant execute on function public.set_weekly_officer_member_v1(uuid,uuid,boolean,text,boolean,text) to authenticated;\ngrant execute on function public.reorder_weekly_officer_v1(uuid,uuid[]) to authenticated;\ngrant execute on function public.save_weekly_officer_absence_v1(uuid,uuid,uuid,text,date,date,text) to authenticated;\ngrant execute on function public.delete_weekly_officer_absence_v1(uuid,uuid) to authenticated;\ngrant execute on function public.save_weekly_dinner_v1(uuid,uuid,date,uuid,text,text,text,text) to authenticated;\ngrant execute on function public.set_weekly_dinner_closed_v1(uuid,uuid,boolean,text) to authenticated;\ngrant execute on function public.request_weekly_officer_swap_v1(uuid,uuid,uuid,text) to authenticated;\ngrant execute on function public.respond_weekly_officer_swap_v1(uuid,uuid,boolean,text) to authenticated;\ngrant execute on function public.mark_weekly_officer_swap_applied_v1(uuid,uuid,text) to authenticated;\ngrant execute on function public.cancel_weekly_officer_swap_v1(uuid,uuid) to authenticated;\n\n-- Internal helpers are not API endpoints.\nrevoke execute on function public.weekly_officer_notify_member_v1(uuid,uuid,text,text,text,uuid) from public,anon,authenticated;\nrevoke execute on function public.rebuild_weekly_officer_schedule_internal_v1(uuid,date,date) from public,anon,authenticated;\nrevoke execute on function public.rebuild_weekly_officer_future_internal_v1(uuid,date) from public,anon,authenticated;\nrevoke execute on function public.weekly_officer_member_append_trigger_v1() from public,anon,authenticated;\n\n-- Ensure timestamp audit columns remain server-stamped for direct trigger-side changes.\ncreate or replace function public.weekly_officer_touch_updated_v1()\nreturns trigger\nlanguage plpgsql\nset search_path=public\nas $$\nbegin\n  new.updated_at:=now();\n  if (select auth.uid()) is not null then new.updated_by:=(select auth.uid()); end if;\n  return new;\nend;\n$$;\n\ndrop trigger if exists trg_weekly_officer_rotation_touch on public.weekly_officer_rotation;\ncreate trigger trg_weekly_officer_rotation_touch before update on public.weekly_officer_rotation\nfor each row execute function public.weekly_officer_touch_updated_v1();\ndrop trigger if exists trg_weekly_officer_absences_touch on public.weekly_officer_absences;\ncreate trigger trg_weekly_officer_absences_touch before update on public.weekly_officer_absences\nfor each row execute function public.weekly_officer_touch_updated_v1();\ndrop trigger if exists trg_weekly_dinners_touch on public.weekly_dinners;\ncreate trigger trg_weekly_dinners_touch before update on public.weekly_dinners\nfor each row execute function public.weekly_officer_touch_updated_v1();\ndrop trigger if exists trg_weekly_officer_swaps_touch on public.weekly_officer_swap_requests;\ncreate trigger trg_weekly_officer_swaps_touch before update on public.weekly_officer_swap_requests\nfor each row execute function public.weekly_officer_touch_updated_v1();\n\nrevoke execute on function public.weekly_officer_touch_updated_v1() from public,anon,authenticated;\n", 'supabase/migrations/20260812091054_rc1_weekly_officer_security_hardening.sql': '-- Commit 12 — hardening: helper de disponibilidade é apenas interno.\nrevoke execute on function public.weekly_officer_member_available_v1(uuid,uuid,date)\n  from public, anon, authenticated;\n', 'supabase/migrations/20260812091155_rc1_weekly_officer_history_guard.sql': "-- Commit 12 — nunca fabricar histórico de anos anteriores.\ncreate or replace function public.ensure_weekly_officer_schedule_v1(target_club uuid,p_year integer)\nreturns integer language plpgsql security definer set search_path=public as $$\ndeclare v_start date; v_end date; v_first date; v_inserted integer:=0; v_current_year integer;\nbegin\n  if (select auth.uid()) is null or not public.has_club_access(target_club) then\n    raise exception 'Sem acesso ao clube.';\n  end if;\n  if p_year<2020 or p_year>2100 then raise exception 'Ano inválido.'; end if;\n\n  v_current_year:=extract(year from current_date)::int;\n  if p_year<v_current_year then return 0; end if;\n\n  v_start:=make_date(p_year,1,1);\n  v_end:=make_date(p_year,12,31);\n  if p_year=v_current_year then v_start:=greatest(v_start,current_date); end if;\n  v_first:=v_start + ((4-extract(dow from v_start)::int+7)%7);\n\n  insert into public.weekly_dinners(club_id,dinner_date,dinner_kind,status,assignment_source,generated)\n  select target_club,gs::date,'regular','planned','auto',true\n  from generate_series(v_first::timestamp,v_end::timestamp,interval '7 day') gs\n  on conflict (club_id,dinner_date,dinner_kind) do nothing;\n  get diagnostics v_inserted=row_count;\n  perform public.rebuild_weekly_officer_schedule_internal_v1(target_club,v_first,v_end);\n  return v_inserted;\nend;\n$$;\n\nrevoke execute on function public.ensure_weekly_officer_schedule_v1(uuid,integer) from public,anon;\ngrant execute on function public.ensure_weekly_officer_schedule_v1(uuid,integer) to authenticated;\n"}

def write_file(rel, content):
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding='utf-8')

def replace_once(rel, old, new):
    path = ROOT / rel
    text = path.read_text(encoding='utf-8')
    if new in text:
        return
    if old not in text:
        raise SystemExit(f'ERRO: bloco esperado não encontrado em {rel}')
    path.write_text(text.replace(old, new, 1), encoding='utf-8')

for rel, content in FILES.items():
    write_file(rel, content)

